const GROUPS=[{"id": "it", "name": "IT va dasturlash", "description": "Dasturlar qanday yaratilishi va ishlashini tushuning.", "icon": "</>"}, {"id": "ai", "name": "AI va avtomatlashtirish", "description": "AI vositalari va avtomatik jarayonlarni o‘rganing.", "icon": "✦"}, {"id": "data", "name": "Data analitika", "description": "Ma’lumotdan foydali xulosa chiqarishni o‘rganing.", "icon": "▥"}, {"id": "sales", "name": "Savdo va mijozlar", "description": "Mijoz ehtiyoji, suhbat va sotuv bosqichlari.", "icon": "↗"}, {"id": "marketing", "name": "Marketing va SMM", "description": "Auditoriya, kontent va reklama natijalari.", "icon": "◎"}, {"id": "business", "name": "Biznes va boshqaruv", "description": "Jarayon, jamoa va strategik qarorlar.", "icon": "◇"}, {"id": "finance", "name": "Moliya va buxgalteriya", "description": "Pul, xarajat, foyda va hisob-kitob.", "icon": "₊"}, {"id": "education", "name": "Ta’lim", "description": "Dars, baholash va o‘quv jarayoni.", "icon": "▤"}, {"id": "logistics", "name": "Logistika va ishlab chiqarish", "description": "Mahsulot, zaxira va ta’minot zanjiri.", "icon": "⇄"}, {"id": "hr", "name": "HR va karyera", "description": "Ishga kirish va xodimlar bilan ishlash.", "icon": "♧"}];
const TERMS=[{"id": "legacy-0", "cat": "Savdo va mijozlar", "term": "CRM", "sub": "Mijozlar bilan munosabatlarni boshqarish", "definition": "Mijoz ma’lumotlari, suhbatlari va sotuv bosqichlarini tartibga soladi.\n\nHar bir mijozning kimligi, nimaga qiziqqani, kim bilan gaplashgani va keyingi aloqa sanasi bir joyda saqlanadi. Shu sabab bir xodim boshlab bergan suhbatni boshqasi davom ettira oladi. CRM natija berishi uchun xodimlar ma’lumotni vaqtida kiritishi va har bir mijozga keyingi qadam belgilashi kerak.", "example": "O‘quv markaziga murojaat qilgan ota-onaga ertaga qo‘ng‘iroq qilish vazifasi qo‘yiladi.", "group": "sales", "related": ["legacy-4", "legacy-6", "legacy-7"], "confusion": "", "where": "Mijozlarga qayta aloqani hozir qayerda belgilaysiz?"}, {"id": "legacy-1", "cat": "Biznes va boshqaruv", "term": "ERP", "sub": "Korxona resurslarini boshqarish", "definition": "Savdo, ombor, xarid, moliya va boshqa jarayonlarni umumiy ma’lumotlar bilan bog‘laydi.\n\nBir bo‘lim kiritgan ma’lumot boshqa tegishli bo‘limlarning hisobida ishlatilishi mumkin: sotuv buyurtmasi ombor, ishlab chiqarish va moliyaga bog‘lanadi. Rahbar bo‘limlardan alohida hisobot yig‘ish o‘rniga umumiy holatni ko‘radi. Lekin modullar mavjudligi ularning barcha jarayonni avtomatik bajarishini anglatmaydi; mijoz jarayoni bilan mosligini tekshirish kerak.", "example": "Sotuv buyurtmasi ombor va moliya jarayoniga uzatiladi.", "group": "business", "related": ["legacy-18", "legacy-27", "legacy-51"], "confusion": "", "where": "Bo‘limlaringiz ma’lumotlari hozir qanday bog‘langan?"}, {"id": "legacy-2", "cat": "Logistika va ishlab chiqarish", "term": "MRP", "sub": "Material ehtiyojini rejalashtirish", "definition": "Buyurtma, mahsulot tarkibi, qoldiq va muddatdan material ehtiyojini hisoblaydi.\n\nHisobning boshlanish nuqtasi — nechta mahsulot, qaysi sanagacha tayyor bo‘lishi kerakligi. Tizim mahsulot tarkibi, mavjud qoldiq, rejalashtirilgan kelim va yetkazish muddatini solishtirib material xaridini rejalashtiradi. Ombor qoldig‘i yoki sarf me’yori xato bo‘lsa, reja ham xato chiqishi mumkin. Uskuna va xodim quvvatini hisoblash alohida imkoniyat bo‘lishi mumkin.", "example": "100 stol uchun 400 oyoq kerak; omborda 100 ta bo‘lsa, yana 300 ta zarur.", "group": "logistics", "related": ["legacy-5", "legacy-20", "legacy-21"], "confusion": "", "where": "Materialni qancha va qachon olishni qanday hisoblaysiz?"}, {"id": "legacy-3", "cat": "AI va avtomatlashtirish", "term": "AI agent", "sub": "Vazifa bajaruvchi AI yordamchi", "definition": "Ma’lumotni tushunib, ruxsat etilgan vositalar orqali amal bajaradigan tizim.\n\nAgentga maqsad, bilim manbasi, bajarishi mumkin bo‘lgan amallar va chegaralar beriladi. U savolni tushunib, kerakli ma’lumotni topishi, CRM’ga yozishi yoki uchrashuv yaratishi mumkin — faqat tegishli ulanish va ruxsat bo‘lsa. Uni baholashda chiroyli javobdan tashqari vazifani to‘g‘ri bajargani, xatolar va xodimga uzatish holatlari tekshiriladi.", "example": "Savolga javob beradi va mijoz roziligi bilan CRM’da murojaat yaratadi.", "group": "ai", "related": ["legacy-19", "legacy-38", "legacy-39"], "confusion": "", "where": "Agent javobdan tashqari qaysi ishni bajarishi kerak?"}, {"id": "legacy-4", "cat": "Savdo va mijozlar", "term": "B2B", "sub": "Biznesdan biznesga savdo", "definition": "Mahsulot yoki xizmatni boshqa korxonaga sotish.\n\nBunday sotuvda foydalanuvchi, xaridni tasdiqlovchi rahbar va texnik mutaxassis turli odamlar bo‘lishi mumkin. Har biri yechimni o‘z mezoni bilan baholaydi: foydalanish qulayligi, iqtisodiy foyda yoki texnik moslik. Shuning uchun bitta suhbatdoshning qiziqishi butun kompaniya xaridga tayyorligini anglatmaydi.", "example": "IT kompaniya mebel korxonasiga ERP taklif qiladi.", "group": "sales", "related": ["legacy-0", "legacy-6", "legacy-7"], "confusion": "", "where": "Xarid qarorini korxonangizda kim qabul qiladi?"}, {"id": "legacy-5", "cat": "Logistika va ishlab chiqarish", "term": "BOM", "sub": "Mahsulot tarkibi", "definition": "Bitta mahsulot uchun kerakli material va qismlar ro‘yxati.\n\nRo‘yxatda qismlar nomi, miqdori va o‘lchov birligi yoziladi; murakkab mahsulotda bir nechta daraja bo‘lishi mumkin. Shu tarkib material ehtiyoji va tannarx hisobiga asos bo‘ladi. Ishlab chiqarishdagi yo‘qotish yoki chiqindi me’yorlari bo‘lsa, ular ham tegishli tartibda hisobga olinadi. Mahsulot o‘zgarsa, tarkibni yangilash muhim.", "example": "Bir stol: 1 ustki qism, 4 oyoq, 8 vint.", "group": "logistics", "related": ["legacy-2", "legacy-20", "legacy-21"], "confusion": "", "where": "Mahsulot tarkibi va sarf me’yorlari yozilganmi?"}, {"id": "legacy-6", "cat": "Savdo va mijozlar", "term": "Lid", "sub": "Potensial mijoz murojaati", "definition": "Qiziqish bildirgan shaxs yoki korxona. Hali xarid qilishi aniq emas.\n\nMurojaat reklama, tavsiya, sayt yoki telefon orqali kelishi mumkin. Dastlab uning ehtiyoji, kompaniyasi va aloqa ma’lumoti aniqlanadi; keyin xizmatga mosligi tekshiriladi. Bir odam bir necha marta murojaat qilsa, uni bir nechta yangi mijoz deb sanamaslik kerak. Lid soni bilan haqiqiy sotuv imkoniyatlari soni farqlanadi.", "example": "Reklama orqali telefon qoldirgan korxona egasi.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-7"], "confusion": "", "where": "Qaysi vazifani hal qilish uchun murojaat qildingiz?"}, {"id": "legacy-7", "cat": "Savdo va mijozlar", "term": "Kvalifikatsiya", "sub": "Mijozga moslikni tekshirish", "definition": "Ehtiyoj, vakolat, muddat va budjetni o‘rganish.\n\nBu mijozni so‘roqqa tutish emas, ikki tomon vaqtini foydali ishlatish uchun moslikni aniqlashdir. Muammo, uning ahamiyati, xarid jarayoni, rejalashtirilgan vaqt va moliyaviy imkoniyat suhbat davomida o‘rganiladi. Mos kelmagan mijozga asossiz taklif berish o‘rniga sababini qayd qilish yoki boshqa yo‘lni tavsiya etish mumkin.", "example": "Mijozga ombor yechimi kerak, lekin qarorni direktor qabul qiladi.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Bu masalani qachongacha hal qilmoqchisiz?"}, {"id": "legacy-8", "cat": "Savdo va mijozlar", "term": "Discovery", "sub": "Ehtiyojni o‘rganish suhbati", "definition": "Hozirgi jarayon, muammo va uning ta’sirini savollar bilan aniqlash.\n\nAvval mijoz hozir qanday ishlashini aytadi, siz esa jarayonni tushunish uchun aniqlashtiruvchi savollar berasiz. Muammo qanchalik tez-tez uchrashi, kimga ta’sir qilishi va qanday yo‘qotish keltirishi o‘rganiladi. Oxirida tushunganlaringizni mijozga qisqa qaytarib tasdiqlating. Shundan keyin mos demo yoki taklifni tayyorlash osonlashadi.", "example": "Buyurtmalar qanday qabul qilinishi va qayerda yo‘qolishi o‘rganiladi.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Hozir jarayon boshidan oxirigacha qanday ishlaydi?"}, {"id": "legacy-9", "cat": "Savdo va mijozlar", "term": "Pain point", "sub": "Mijozning og‘riqli muammosi", "definition": "Vaqt, pul yoki sifat yo‘qotishiga olib keladigan qiyinchilik.\n\nUmumiy istak bilan aniq muammoni ajrating: “AI kerak” — istak, “kechasi javob bo‘lmagani uchun murojaat yo‘qoladi” — tekshiriladigan muammo. Uning tez-tezligi va ta’sirini savollar bilan aniqlang. Bitta alomatning bir nechta sababi bo‘lishi mumkin; mahsulot taklif qilishdan oldin ildiz sababni tushunish muhim.", "example": "Administrator kech javob bergani uchun murojaatlar soviydi.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Bu muammo ish natijasiga qanday ta’sir qilyapti?"}, {"id": "legacy-10", "cat": "Savdo va mijozlar", "term": "Decision maker", "sub": "Qaror qabul qiluvchi", "definition": "Xaridni tasdiqlash vakolatiga ega shaxs.\n\nSuhbatlashayotgan odam yechimni ishlatishi yoki tavsiya qilishi mumkin, ammo to‘lovni tasdiqlash vakolati bo‘lmasligi mumkin. Qarorni kim, qanday mezon va tartib bilan qabul qilishini muloyim so‘rang. Texnik, moliyaviy va operatsion tomonlarning roziligi ham zarur bo‘lishi mumkin. Uchrashuvga tegishli kishilarni taklif qilish jarayonni aniqlashtiradi.", "example": "Administrator foydalanadi, direktor xaridni tasdiqlaydi.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Yechimni tanlashda yana kim qatnashadi?"}, {"id": "legacy-11", "cat": "Savdo va mijozlar", "term": "Demo", "sub": "Amaliy namoyish", "definition": "Mahsulotni mijozning vazifasiga mos holatda ko‘rsatish.\n\nYaxshi demo barcha tugmalarni ketma-ket ko‘rsatishdan ko‘ra mijozning bitta muhim vazifasini boshidan oxirigacha bajaradi. Avval qaysi muammo ko‘rsatilishini kelishing, keyin tegishli jarayonni namoyish qiling. Namoyishdagi tayyor imkoniyat bilan hali ishlab chiqilishi kerak bo‘lgan ishni ajrating. Yakunda moslik va keyingi qadamni muhokama qiling.", "example": "Omborga mahsulot kirim qilib, qoldiqni ko‘rsatish.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Uchrashuvda qaysi jarayonni ko‘rsatish foydali?"}, {"id": "legacy-12", "cat": "Savdo va mijozlar", "term": "Tijorat taklifi", "sub": "Yechim va narx yozilgan taklif", "definition": "Ish tarkibi, muddat, narx va shartlarni tushuntiradi.\n\nTaklif mijozning muammosi, tavsiya etilgan yechim va kutiladigan natijani bog‘lashi kerak. Bir martalik ishlar, obuna, qo‘llab-quvvatlash, cheklovlar va mijozning majburiyatlari tushunarli yoziladi. Narx faqat raqamdan iborat bo‘lsa, mijoz nimaga to‘layotganini baholay olmaydi. Muhim taxminlarni va taklifning amal qilish muddatini ham kelishing.", "example": "Uch modul, ma’lumot ko‘chirish va o‘qitish narxi ajratiladi.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Taklifni baholashda siz uchun asosiy mezon nima?"}, {"id": "legacy-13", "cat": "Savdo va mijozlar", "term": "E’tiroz", "sub": "Xaridga oid xavotir", "definition": "Narx, vaqt, ishonch yoki moslik haqidagi to‘siq.\n\nE’tiroz darhol rad etish degani emas; u hal qilinmagan savolni ko‘rsatishi mumkin. Avval gapni bo‘lmasdan tinglang, so‘ng aynan qaysi jihat tashvish tug‘dirganini aniqlang. Dalil, demo yoki shartlarni tushuntirish bilan javob bering. Mijozning ehtiyojiga mos kelmaydigan yechimni bosim bilan sotishga urinmang.", "example": "“Xodimlar yangi tizimga ko‘nika olmaydi.”", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Aynan qaysi jihati sizni xavotirga solyapti?"}, {"id": "legacy-14", "cat": "Savdo va mijozlar", "term": "Follow-up", "sub": "Qayta aloqa", "definition": "Oldingi suhbatdan keyin kelishilgan vaqtda aloqani davom ettirish.\n\nHar bir keyingi aloqa mijozga aniq foyda berishi kerak: javob, demo, yangilangan taklif yoki kelishilgan qarorni muhokama qilish. Suhbat oxirida vaqt, kanal va vazifani belgilab CRM’ga yozing. Faqat “o‘ylab ko‘rdingizmi?” deb qayta-qayta yozishdan ko‘ra oldingi savolga mazmunli qaytish foydaliroq. Mijozning aloqa istagini hurmat qiling.", "example": "Taklif muhokamasi uchun payshanba kuni qo‘ng‘iroq qilish.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Taklifni qachon birga ko‘rib chiqamiz?"}, {"id": "legacy-15", "cat": "Savdo va mijozlar", "term": "Pipeline", "sub": "Faol sotuv imkoniyatlari", "definition": "Mijozlar va ularning hozirgi sotuv bosqichlari.\n\nHar bir faol imkoniyatning mas’uli, bosqichi, ehtimoliy summasi va keyingi vazifasi bo‘ladi. Bu ro‘yxat qaysi kelishuv qayerda to‘xtaganini ko‘rishga yordam beradi. Bosqich o‘zgarishi mijozning haqiqiy harakati bilan tasdiqlanishi kerak. Taklif yuborilganini shartnoma tuzildi deb yoki taxminiy summani tushum deb hisoblamang.", "example": "3 mijoz demo kutmoqda, 2 mijoz taklifni ko‘rib chiqmoqda.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Bu mijoz bilan keyingi aniq qadam nima?"}, {"id": "legacy-16", "cat": "Savdo va mijozlar", "term": "Konversiya", "sub": "Bosqichlar orasidagi o‘tish ulushi", "definition": "Keyingi bosqichga o‘tganlar soni oldingi bosqich soniga bo‘linadi.\n\nHisobda surat — keyingi bosqichga o‘tganlar, maxraj — boshlang‘ich bosqichdagi guruh. Taqqoslashda bir xil davr, kanal va mijozlar guruhini olish kerak. Past ko‘rsatkichning sababi lid sifati, javob tezligi yoki taklif mosligi bo‘lishi mumkin. Juda kichik namunadan katta xulosa chiqarishdan oldin ko‘proq kuzatuv yig‘ing.", "example": "20 lidning 5 tasi uchrashuvga keldi: 25%.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Mijozlar ko‘proq qaysi bosqichda to‘xtayapti?"}, {"id": "legacy-17", "cat": "Savdo va mijozlar", "term": "ROI", "sub": "Investitsiya qaytimi", "definition": "Foydaning xarajatga nisbatini baholash. Taxminlarni dalil bilan tekshirish kerak.\n\nOddiy hisob: investitsiyadan kelgan sof foydani investitsiya xarajatiga bo‘lib, 100 ga ko‘paytiriladi. Davr, xarajatlar va foyda qanday hisoblanganini ochiq yozish kerak. Vaqt tejalishi har doim darhol pul tushumiga aylanmaydi. Mijozning haqiqiy raqamlariga tayaning; sotuvni yoki foydani kafolatlaydigan asossiz foizlar bermang.", "example": "Yechim xarajati va tasdiqlangan tejamni solishtirish.", "group": "sales", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "where": "Hozir bu jarayonga qancha vaqt va mablag‘ sarflaysiz?"}, {"id": "legacy-18", "cat": "Biznes va boshqaruv", "term": "Biznes jarayon", "sub": "Natijaga olib boradigan qadamlar", "definition": "Bir-biriga bog‘langan ishlar ketma-ketligi.\n\nHar bir qadamning mas’uli, kiruvchi ma’lumoti va chiqadigan natijasi mavjud. Jarayonni chizish yoki yozib chiqish qayerda kutish, takroriy kiritish va xato borligini ko‘rsatadi. Dastur tanlashdan oldin shu ketma-ketlikni tushunish kerak. Noto‘g‘ri tashkil qilingan jarayonni avtomatlashtirish uning muammosini ham tezlashtirishi mumkin.", "example": "Buyurtma → tayyorlash → jo‘natish → to‘lov.", "group": "business", "related": ["legacy-1", "legacy-27", "legacy-51"], "confusion": "", "where": "Qaysi bosqichda eng ko‘p kechikish bor?"}, {"id": "legacy-19", "cat": "AI va avtomatlashtirish", "term": "Avtomatlashtirish", "sub": "Takroriy ishni tizimga topshirish", "definition": "Qoidaga mos ishni kamroq qo‘l mehnati bilan bajarish.\n\nQaysi hodisa ishni boshlashi, qaysi shart tekshirilishi va qanday natija kerakligi belgilanadi. Aniq qoidali takroriy ishlar odatda yaxshi nomzod bo‘ladi. Istisno holatlar, xatolar va inson tasdig‘i qayerda kerakligi ham rejalashtiriladi. Natija faqat ishlagani bilan emas, vaqt, xato yoki xizmat sifatiga ta’siri bilan baholanadi.", "example": "To‘lov muddati o‘tsa mas’ulga eslatma yaratiladi.", "group": "ai", "related": ["legacy-3", "legacy-38", "legacy-39"], "confusion": "", "where": "Qaysi ishni har kuni qayta bajarasiz?"}, {"id": "legacy-20", "cat": "Logistika va ishlab chiqarish", "term": "SKU", "sub": "Mahsulotning alohida kodi", "definition": "Mahsulot variantini hisobda ajratadigan identifikator.\n\nSKU mahsulotni kompaniya ichida aniq ajratishga yordam beradi. O‘lcham, rang yoki komplekt o‘zgarsa, biznes qoidasiga ko‘ra alohida kod berilishi mumkin. Uni shtrix-kod yoki mahsulot nomi bilan aynan bir tushuncha deb qabul qilmang. Kodlar takrorlanmasligi va eski-yangi tizimlarda mos kelishi ombor hamda integratsiya uchun muhim.", "example": "Bir futbolkaning oq va qora variantlari alohida kodda.", "group": "logistics", "related": ["legacy-2", "legacy-5", "legacy-21"], "confusion": "", "where": "Mahsulot turlari qanday kodlanadi?"}, {"id": "legacy-21", "cat": "Logistika va ishlab chiqarish", "term": "Inventarizatsiya", "sub": "Haqiqiy qoldiqni tekshirish", "definition": "Ombordagi mahsulotni hisobdagi son bilan solishtirish.\n\nMahsulot sanaladi, o‘lchanadi yoki tegishli usulda tekshiriladi, so‘ng hisob bilan taqqoslanadi. Tafovut chiqsa, sababini aniqlash kerak: kiritilmagan kirim-chiqim, noto‘g‘ri birlik yoki boshqa xato bo‘lishi mumkin. Farqni shunchaki o‘zgartirib qo‘yish sababni bartaraf etmaydi. Sana, mas’ul va tuzatish tartibi belgilanadi.", "example": "Tizimda 50, haqiqiy omborda 47 dona topildi.", "group": "logistics", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "where": "Oxirgi sanashda qancha tafovut chiqdi?"}, {"id": "legacy-22", "cat": "Moliya va buxgalteriya", "term": "Tannarx", "sub": "Mahsulotga tegishli xarajat", "definition": "Mahsulotni olish yoki tayyorlash xarajatlari; tarkibi hisob usuliga bog‘liq.\n\nTannarxga qaysi xarajatlar kirishi biznes turi va hisob siyosatiga bog‘liq. Material qiymatidan tashqari tegishli mehnat va boshqa xarajatlar hisoblanishi mumkin. Sotuv narxi bilan tannarx farqi barcha korxona xarajatlaridan keyingi sof foyda degani emas. Mijozdan hisob usuli, birlik va taqsimlash qoidalarini aniqlang.", "example": "Material, ishlab chiqarish mehnati va tegishli xarajatlar.", "group": "finance", "related": ["legacy-23", "legacy-24", "legacy-25"], "confusion": "", "where": "Tannarxni hozir qanday hisoblaysiz?"}, {"id": "legacy-23", "cat": "Moliya va buxgalteriya", "term": "Debitorlik", "sub": "Sizga to‘lanishi kerak bo‘lgan qarz", "definition": "Mijoz yoki boshqa tomonning korxonaga qarzi.\n\nQarzning summasi, to‘lov muddati va kimga tegishli ekanini kuzatish kerak. Muddati o‘tgan qarz bilan hali muddati kelmagan qarz alohida tahlil qilinadi. Korxona ko‘p sotgan bo‘lsa ham, mijozlar to‘lamasa pul oqimi qiyinlashadi. Hisobot, eslatma va mas’ul xodim vazifalari qarzni nazorat qilishga yordam beradi.", "example": "Mahsulot yetkazildi, mijoz hali 10 mln so‘m to‘lamadi.", "group": "finance", "related": ["legacy-22", "legacy-24", "legacy-25"], "confusion": "", "where": "Mijoz qarzlarini qanday kuzatasiz?"}, {"id": "legacy-24", "cat": "Moliya va buxgalteriya", "term": "Kreditorlik", "sub": "Siz to‘lashingiz kerak bo‘lgan qarz", "definition": "Korxonaning yetkazib beruvchi yoki boshqa tomonga qarzi.\n\nBu qarzning kimga, qancha va qachon to‘lanishi kerakligi rejalashtiriladi. To‘lovlar pul tushumlari bilan solishtirilsa, mablag‘ yetishmasligi oldindan ko‘rinishi mumkin. Yetkazib beruvchilar bilan kelishilgan muddatlar va hujjatlar muhim. Qarzdorlik hisobotidagi raqam bilan bank hisobidagi pul qoldig‘i bir xil ko‘rsatkich emas.", "example": "Material olindi, yetkazib beruvchiga to‘lov hali qilinmadi.", "group": "finance", "related": ["legacy-22", "legacy-23", "legacy-25"], "confusion": "", "where": "Yetkazib beruvchilarga to‘lov muddati qayerda yuritiladi?"}, {"id": "legacy-25", "cat": "Moliya va buxgalteriya", "term": "Cash flow", "sub": "Pul oqimi", "definition": "Pulning real kirishi va chiqishi. Foyda bilan bir xil emas.\n\nTushum va chiqim real pul harakatini ko‘rsatadi; reja esa kelajakdagi kutilayotgan harakatni ko‘rsatadi. Nasiya sotuv daromad sifatida tan olinishi mumkin, pul esa keyin keladi. Shu sabab foydali korxonada ham vaqtincha pul yetishmovchiligi bo‘lishi mumkin. Mijozga tarixiy hisobot kerakmi yoki kelgusi to‘lovlar rejasi kerakmi, aniqlang.", "example": "Savdo bo‘ldi, lekin pul keyingi oy tushadi.", "group": "finance", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "where": "Pul tushumi va to‘lovlar rejasini tuzasizmi?"}, {"id": "legacy-26", "cat": "Data analitika", "term": "Dashboard", "sub": "Boshqaruv ko‘rsatkichlari ekrani", "definition": "Muhim sonlar va grafiklarni bir joyda ko‘rsatadi.\n\nKo‘rsatkichlar tanlangan sana, filial va boshqa filtrlar bo‘yicha jamlanadi. Har bir raqamning manbasi, hisoblash usuli va yangilanish vaqti aniq bo‘lishi kerak. Chiroyli grafikning o‘zi ma’lumot to‘g‘riligini kafolatlamaydi. Rahbar qaysi qarorni qabul qilmoqchi ekaniga qarab ekran tarkibini tanlash foydaliroq.", "example": "Daromad, xarajat va pul qoldig‘i bitta ekranda.", "group": "data", "related": ["legacy-52", "data-0", "data-1"], "confusion": "", "where": "Har kuni qaysi ko‘rsatkichlarni ko‘rishingiz kerak?"}, {"id": "legacy-27", "cat": "Biznes va boshqaruv", "term": "KPI", "sub": "Natijani baholash ko‘rsatkichi", "definition": "Maqsadga erishishni o‘lchaydigan belgilangan mezon.\n\nKo‘rsatkichning nomi, hisoblash qoidasi, davri va maqsadi oldindan belgilanadi. Faollik ko‘rsatkichlari, masalan qo‘ng‘iroqlar soni, natija ko‘rsatkichlari bilan birga ko‘riladi. Ko‘p qo‘ng‘iroq har doim ko‘p sifatli uchrashuv degani emas. Sinov oyida rahbar bilan qaysi natija asosiy ekanini kelishish muhim.", "example": "Haftalik sifatli uchrashuvlar soni.", "group": "business", "related": ["legacy-1", "legacy-18", "legacy-51"], "confusion": "", "where": "Sinov oyida natija qaysi ko‘rsatkich bilan baholanadi?"}, {"id": "legacy-28", "cat": "IT va dasturlash", "term": "Implementation", "sub": "Tizimni joriy qilish", "definition": "Sozlash, ma’lumot ko‘chirish, o‘qitish va ishga tushirish.\n\nJoriy qilishda biznes jarayoni o‘rganiladi, tizim sozlanadi, ma’lumotlar tekshiriladi va xodimlar o‘qitiladi. Har ikki tomon mas’uli va vazifalari belgilanadi. Dasturga kirish imkonini berish loyihaning to‘liq yakunlangani emas. Qabul qilish mezonlari va ishga tushgandan keyingi yordamni oldindan kelishish kerak.", "example": "ERP’ni ikki filialga bosqichma-bosqich o‘rnatish.", "group": "it", "related": ["legacy-29", "legacy-30", "legacy-31"], "confusion": "", "where": "Joriy qilishda mijoz tomonidan kim mas’ul bo‘ladi?"}, {"id": "legacy-29", "cat": "IT va dasturlash", "term": "Konfiguratsiya", "sub": "Mavjud sozlamalarni moslash", "definition": "Dasturdagi tayyor parametrlarni o‘zgartirish.\n\nBu tayyor imkoniyatlardan foydalanib biznes qoidalarini belgilashdir: huquqlar, bosqichlar, omborlar yoki boshqa parametrlar. Odatda kodga yangi funksiya yozish talab qilinmaydi, lekin mahsulotga qarab farq qiladi. Sozlama boshqa jarayonga ta’sir qilishi mumkin, shuning uchun uni sinab ko‘rish kerak. Standart imkoniyatni tekshirmasdan maxsus ishlab chiqish taklif qilmang.", "example": "Omborlar va foydalanuvchi huquqlarini yaratish.", "group": "it", "related": ["legacy-28", "legacy-30", "legacy-31"], "confusion": "", "where": "Bu ehtiyoj tayyor sozlama bilan bajariladimi?"}, {"id": "legacy-30", "cat": "IT va dasturlash", "term": "Customization", "sub": "Maxsus o‘zgartirish", "definition": "Mijoz ehtiyoji uchun yangi funksiya yoki o‘zgarish yaratish.\n\nStandart funksiyalar talabni qondirmaganda dasturga maxsus o‘zgarish kiritilishi mumkin. Talab, narx, muddat va keyingi yangilanishlarga ta’sir texnik jamoa bilan baholanadi. Mijoz xohlagan har bir o‘zgarish albatta foydali degani emas. Avval tayyor imkoniyat bilan ish jarayonini moslashtirish mumkinligini ko‘rib chiqing.", "example": "Korxonaga xos yangi hisobot ishlab chiqish.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-31"], "confusion": "", "where": "Bu talab standart mahsulotda bormi?"}, {"id": "legacy-31", "cat": "IT va dasturlash", "term": "Integratsiya", "sub": "Tizimlarni bog‘lash", "definition": "Ikki tizim o‘rtasida ma’lumot almashish va amallarni ulash.\n\nFaqat tizimlar nomini aytish yetarli emas: qaysi ma’lumot, qaysi yo‘nalishda, qanchalik tez va qaysi amal bilan almashishi aniqlanadi. Mahsulot kodlari va boshqa maydonlar moslashtiriladi. Xato, takroriy yozuv va ulanish uzilishi uchun tartib kerak. API mavjudligi barcha talab oson bajarilishini kafolatlamaydi.", "example": "Saytdagi buyurtma CRM’ga keladi.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Qaysi tizim bilan qaysi ma’lumot almashishi kerak?"}, {"id": "legacy-32", "cat": "IT va dasturlash", "term": "Migratsiya", "sub": "Ma’lumotni ko‘chirish", "definition": "Eski tizimdan yangisiga ma’lumot olib o‘tish.\n\nAvval manba ma’lumotlari olinadi, tozalanadi va yangi tizim maydonlariga moslashtiriladi. Sinov ko‘chirishda sonlar, qoldiqlar va bog‘lanishlar tekshiriladi. Tarixiy hujjatlar bilan faqat boshlang‘ich qoldiqlarni ko‘chirish turli ish hajmlaridir. Zaxira nusxa, to‘xtash vaqti va yakuniy tasdiq tartibini kelishish kerak.", "example": "Excel’dagi tovarlar va qoldiqlarni ERP’ga yuklash.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Ma’lumotlar qaysi formatda va qanchalik toza?"}, {"id": "legacy-33", "cat": "IT va dasturlash", "term": "TZ", "sub": "Texnik topshiriq", "definition": "Bajariladigan ish va qabul qilish shartlari yozilgan hujjat.\n\nYaxshi topshiriq umumiy istakni tekshiriladigan talabga aylantiradi. Qaysi foydalanuvchi nima qiladi, kiruvchi ma’lumot, kutiladigan natija va istisno holatlar yoziladi. “Agent yaxshi ishlasin” o‘rniga qaysi vaziyatda qanday javob yoki amal kerakligi belgilanadi. Bu hujjat sotuv, texnik jamoa va mijoz tushunchasini birlashtiradi.", "example": "Agent savollari, kanallari va xodimga topshirish qoidasi yoziladi.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Ish bajarilganini qaysi mezon bilan tekshiramiz?"}, {"id": "legacy-34", "cat": "IT va dasturlash", "term": "Scope", "sub": "Kelishilgan ish hajmi", "definition": "Loyihaga kiradigan va kirmaydigan ishlarning chegarasi.\n\nIsh hajmi modullar, filiallar, foydalanuvchilar, integratsiyalar va xizmatlar bo‘yicha aniqlanadi. Qo‘shimcha talab paydo bo‘lsa, uning narx va muddatga ta’siri kelishiladi. Noaniq chegaralar ikki tomon kutgan natijani farqlantirishi mumkin. Taklifda bajariladigan ishlar bilan mijoz tayyorlashi kerak bo‘lgan ma’lumotlarni ham ajrating.", "example": "2 filial, 3 modul, 1 integratsiya.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Narxga aynan qaysi ishlar kiradi?"}, {"id": "legacy-35", "cat": "IT va dasturlash", "term": "Pilot / PoC", "sub": "Cheklangan sinov", "definition": "Pilot kichik hajmda amaliy sinov; PoC yechim ishlashini tekshirish.\n\nPoC texnik yoki funksional g‘oya amalga oshishini isbotlashga qaratiladi; pilot esa cheklangan real muhitda ishlashni sinaydi. Sinov uchun muddat, hajm va muvaffaqiyat mezonlari belgilanadi. Bitta vaziyatda ishlagani barcha sharoitda tayyorligini anglatmaydi. Sinovdan keyin natijani baholab, kengroq joriy qilish haqida qaror qilinadi.", "example": "Avval bir filialda jarayonni sinash.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Sinov muvaffaqiyatini qanday o‘lchaymiz?"}, {"id": "legacy-36", "cat": "IT va dasturlash", "term": "Go-live", "sub": "Haqiqiy ishga tushish", "definition": "Tizimdan kundalik real ishda foydalanishni boshlash.\n\nBu paytda xodimlar haqiqiy buyurtma va ma’lumotlarni yangi tizimda yurita boshlaydi. Oldindan ma’lumot tekshiruvi, huquqlar, o‘qitish va yordam kanali tayyor bo‘lishi kerak. Dastlabki kunlarda xatolarni tez kuzatish va hal qilish muhim. Eski tizim bilan parallel ishlash yoki qaytish rejasi loyiha sharoitiga qarab kelishiladi.", "example": "Dushanbadan yangi buyurtmalar ERP’da yuritiladi.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Ishga tushishdan oldin nimalar tayyor bo‘lishi kerak?"}, {"id": "legacy-37", "cat": "IT va dasturlash", "term": "SLA", "sub": "Xizmat darajasi kelishuvi", "definition": "Qo‘llab-quvvatlash va xizmat mezonlarini belgilaydi.\n\nKelishuvda xizmat vaqti, nosozlik darajalari hamda javob yoki tiklash maqsadlari belgilanadi. Murojaatga javob berish va muammoni butunlay hal qilish turli muddatlar bo‘lishi mumkin. Istisnolar va mijozning majburiyatlari ham aniq yoziladi. “Yordam bor” deyish o‘rniga aynan qanday yordam ekanini tushuntiring.", "example": "Nosozlikka javob berish muddatini kelishish.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Yordam qaysi vaqtda va qanday shartda beriladi?"}, {"id": "legacy-38", "cat": "AI va avtomatlashtirish", "term": "LLM", "sub": "Katta til modeli", "definition": "Matnni qayta ishlash, tushunish va yaratishda ishlatiladigan model.\n\nModel matndagi bog‘lanishlarni o‘rgangan holda javob yaratadi, lekin kompaniyangizning barcha yangi ma’lumotlarini o‘zidan bilmaydi. Kerakli ma’lumot hujjatlar yoki vositalar orqali taqdim etiladi. Ishonchli ohang to‘g‘ri javobni anglatmaydi. Biznesda modelni bilim manbasi, qoidalar va tekshiruvlar bilan birga ishlatish muhim.", "example": "Mijozning erkin yozilgan savolini talqin qiladi.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-39"], "confusion": "", "where": "Javob qaysi manbaga tayanishi kerak?"}, {"id": "legacy-39", "cat": "AI va avtomatlashtirish", "term": "Prompt", "sub": "AI uchun ko‘rsatma", "definition": "Vazifa, qoidalar va kerakli javob shaklini belgilaydi.\n\nKo‘rsatmada agentning vazifasi, kim uchun ishlashi, manbalari va chegaralari yoziladi. Yaxshi prompt javob ohangi bilan birga noma’lum ma’lumot va xodimga topshirish tartibini ham belgilaydi. Prompt texnik ruxsat o‘rnini bosmaydi: taqiqlangan amal tizim darajasida ham cheklanishi kerak. Turli suhbatlarda sinab, yaxshilang.", "example": "“Tasdiqlangan narxdan foydalan, noma’lumini xodimga topshir.”", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Agent qanday ohangda va qanday qoida bilan javob bersin?"}, {"id": "legacy-40", "cat": "AI va avtomatlashtirish", "term": "Bilim bazasi", "sub": "Tasdiqlangan ma’lumot manbasi", "definition": "Agent foydalanadigan hujjat va ma’lumotlar to‘plami.\n\nHujjatlar dolzarb, bir-biriga zid bo‘lmagan va foydalanishga ruxsat etilgan bo‘lishi kerak. Eskirgan narx yoki jadval agentni noto‘g‘ri javobga olib kelishi mumkin. Ma’lumot egasi, yangilash tartibi va kirish huquqlarini belgilang. Bilim bazasiga hujjat qo‘shish modelni alohida qayta o‘qitish bilan bir xil emas.", "example": "Kurs narxlari, jadval va xizmat shartlari.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Ma’lumotni kim yangilaydi?"}, {"id": "legacy-41", "cat": "AI va avtomatlashtirish", "term": "RAG", "sub": "Manbadan topib javob berish", "definition": "Tegishli hujjat bo‘laklarini topib modelga javob uchun berish usuli.\n\nSavol kelganda tizim tegishli ma’lumotni qidiradi, topilgan bo‘laklarni modelga beradi va model ularga tayanib javob yaratadi. Natija qidiruv sifati, hujjatlarning dolzarbligi va ko‘rsatmalarga bog‘liq. Bu usul yangi hujjatlardan foydalanishga yordam beradi, lekin xatoni butunlay yo‘qotmaydi. Manba topilmasa qanday yo‘l tutilishi belgilanadi.", "example": "Agent kurs jadvalini hujjatdan topadi.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Javob berishda qaysi hujjatlar ishlatiladi?"}, {"id": "legacy-42", "cat": "IT va dasturlash", "term": "API", "sub": "Dasturlar aloqa interfeysi", "definition": "Dasturga ma’lumot olish yoki amal bajarish uchun murojaat usuli.\n\nSo‘rovning manzili, kiritiladigan maydonlar, javob shakli va ruxsat talablari hujjatda belgilanadi. Bir API faqat o‘qishga, boshqasi yozishga imkon berishi mumkin. Limitlar, xatolar va tizim versiyasi integratsiyaga ta’sir qiladi. Siz kod yozmasangiz ham, mijozdan API hujjatini olib texnik jamoaga uzatishni bilishingiz kerak.", "example": "Agent API orqali CRM’da lid yaratadi.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Tizimingizda hujjatlashtirilgan API bormi?"}, {"id": "legacy-43", "cat": "AI va avtomatlashtirish", "term": "Webhook", "sub": "Hodisa haqida avtomatik xabar", "definition": "Hodisa yuz berganda boshqa tizimga xabar yuboradi.\n\nTizim doim ma’lumotni so‘rab tekshirish o‘rniga hodisa sodir bo‘lganda xabar yuboradi. Xabarda yangi buyurtma yoki to‘lov haqida ma’lumot bo‘lishi mumkin. Yetkazilmagan va qayta yuborilgan xabarlarni boshqarish zarur. Xabar haqiqiy manbadan kelganini tekshirish texnik himoyaning bir qismidir.", "example": "Yangi buyurtma kelganda avtomatlashtirish ishga tushadi.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Qaysi hodisa keyingi ishni boshlashi kerak?"}, {"id": "legacy-44", "cat": "AI va avtomatlashtirish", "term": "Workflow", "sub": "Ish ketma-ketligi", "definition": "Vazifani bajaradigan qadamlar va shartlar.\n\nQadamlar orasida shart, kutish, qayta urinish va xatoni xodimga uzatish bo‘lishi mumkin. Har bir bosqichning kiruvchi va chiqadigan ma’lumoti tushunarli bo‘lishi kerak. Ayrim ishlar oddiy qoidalar bilan, ayrimlari AI yordamida bajariladi. Butun jarayonni AI qilish shart emas; mos vosita va nazorat tanlanadi.", "example": "Murojaat → ehtiyoj → CRM → xodimga xabar.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Jarayonning har bir qadamini kim bajaradi?"}, {"id": "legacy-45", "cat": "AI va avtomatlashtirish", "term": "Human handoff", "sub": "Xodimga topshirish", "definition": "AI hal qila olmaydigan holatni inson davom ettirishi.\n\nAgentning vakolati yetmaganda yoki mijoz xodimni so‘raganda suhbat tegishli odamga uzatiladi. Xodimga oldingi suhbat va yig‘ilgan ma’lumot yetkazilsa, mijoz hammasini qayta aytmaydi. Mas’ul va javob vaqti belgilanmasa, uzatishning o‘zi yetarli bo‘lmaydi. Mijozga keyingi qadam tushuntiriladi.", "example": "Mijoz maxsus chegirma so‘rasa sotuvchiga uzatiladi.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Qaysi holatlarda xodim aralashishi kerak?"}, {"id": "legacy-46", "cat": "AI va avtomatlashtirish", "term": "Hallucination", "sub": "AI’ning asossiz javobi", "definition": "Modelning noto‘g‘ri yoki manbada yo‘q ma’lumot berishi.\n\nModel noto‘g‘ri narx, mavjud bo‘lmagan xizmat yoki asossiz fakt aytishi mumkin. Manbaga tayangan javob, cheklangan vositalar va testlar xavfni kamaytiradi. Moliya yoki boshqa muhim amallar uchun qo‘shimcha tekshiruv kerak bo‘lishi mumkin. “AI hech qachon xato qilmaydi” deb aytmang; xatoni kuzatish va tuzatish jarayonini tushuntiring.", "example": "Mavjud bo‘lmagan chegirmani aytishi.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Noma’lum savolga agent qanday yo‘l tutsin?"}, {"id": "legacy-47", "cat": "AI va avtomatlashtirish", "term": "Token", "sub": "Model ishlatadigan matn birligi", "definition": "So‘z yoki uning bo‘lagi bo‘lishi mumkin; hajm va xarajatga ta’sir qiladi.\n\nToken so‘z, so‘z bo‘lagi yoki belgi bo‘lishi mumkin; har bir so‘z aynan bitta token emas. Kiruvchi matn, suhbat tarixi va chiqadigan javob hisobga olinishi mumkin. Tarif va modelga qarab hisoblash qoidasi farqlanadi. Mijozga xarajatni aytishdan oldin foydalanish hajmi va kompaniyaning tasdiqlangan narxlash usulini bilib oling.", "example": "Uzun suhbat va hujjat ko‘proq token talab qilishi mumkin.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Foydalanish xarajatlari tarifga kiradimi?"}, {"id": "legacy-48", "cat": "IT va dasturlash", "term": "Log", "sub": "Amallar va xatolar qaydi", "definition": "Nima sodir bo‘lganini tekshirish uchun saqlanadigan yozuv.\n\nQaydda vaqt, bajarilgan amal, javob va xato kabi ma’lumotlar bo‘lishi mumkin. Bu muammoni topish, xizmatni yaxshilash va bahsli holatni tekshirishga yordam beradi. Maxfiy ma’lumotlar keraksiz saqlanmasligi, kirish huquqi va saqlash muddati belgilanishi kerak. Log yig‘ish bilan birga uni kim kuzatishi ham muhim.", "example": "Agent javobi va CRM’ga yozish xatosi qayd etiladi.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Xatolarni kim kuzatadi va tuzatadi?"}, {"id": "legacy-49", "cat": "IT va dasturlash", "term": "Access control", "sub": "Ruxsatlarni boshqarish", "definition": "Kim qaysi ma’lumotni ko‘rishi va amalni bajarishini belgilaydi.\n\nFoydalanuvchi yoki agentga vazifasi uchun zarur huquqlar beriladi. Ma’lumotni ko‘rish, o‘zgartirish va o‘chirish huquqlari alohida bo‘lishi mumkin. Masalan, agent mijoz kartasini yaratadi, lekin chegirmani tasdiqlay olmaydi. Rol va ruxsatlar ishga tushishdan oldin sinab ko‘riladi; ortiqcha huquq berishdan saqlaning.", "example": "Sotuvchi omborni ko‘radi, ish haqini ko‘rmaydi.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Agentga qaysi amallarga ruxsat beramiz?"}, {"id": "legacy-50", "cat": "IT va dasturlash", "term": "SaaS", "sub": "Xizmat sifatida dastur", "definition": "Dasturdan xizmat modeli orqali, ko‘pincha obuna asosida foydalanish.\n\nDastur xizmat sifatida taqdim etiladi; yangilanish va infratuzilma mas’uliyati shartlarga bog‘liq. Obuna foydalanuvchi, modul yoki foydalanish hajmiga qarab hisoblanishi mumkin. Joriy qilish va maxsus integratsiya obunadan alohida narxlanishi ham mumkin. Internet talabi, ma’lumot eksporti, yordam va bekor qilish shartlarini aniqlang.", "example": "Brauzer orqali foydalanib oylik to‘lov qilish.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Obunaga qaysi xizmat va limitlar kiradi?"}, {"id": "legacy-51", "cat": "Biznes va boshqaruv", "term": "Genix ERP", "sub": "Siz o‘rganayotgan ERP", "definition": "Rasmlarda CRM, ombor, moliya va boshqa modullar ko‘ringan; aniq imkoniyatlarni demoda tekshiring.\n\nBirinchi mashq sifatida bitta mijoz, mahsulot, buyurtma va to‘lov jarayonini kuzating. Modullarning mavjudligidan tashqari ular o‘zaro qanday ma’lumot almashishini o‘rganing. Tayyor funksiya, sozlama va maxsus ishlab chiqish talabini ajrating. Tarif, integratsiya, platforma va AI imkoniyatlarini kompaniyaning amaldagi hujjati yoki demosidan tasdiqlang.", "example": "Bir buyurtmaning ombor va moliyaga ta’sirini kuzating.", "group": "business", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "where": "Bu jarayon Genix’da amalda qanday bajariladi?"}, {"id": "legacy-52", "cat": "Data analitika", "term": "Excel / Google Sheets", "sub": "Jadval bilan ishlash", "definition": "Hisob-kitob, ma’lumot tartiblash va tahlil qilish vositalari.\n\nJadval kichik jarayonlarni tashkil qilish va tahlil qilishda foydali, lekin bir nechta xodim ishlaganda versiyalar, huquqlar va ma’lumot sifati muhimlashadi. CRM yoki ERP bilan jadval birga ishlashi mumkin. Siz Excel tajribangiz orqali mijozning hozirgi hisobini tez tushuna olasiz. Keraksiz almashtirish o‘rniga haqiqiy cheklovni aniqlang.", "example": "Lidlar bosqichlari bo‘yicha konversiyani hisoblash.", "group": "data", "related": ["legacy-26", "data-0", "data-1"], "confusion": "", "where": "Jadvallaringizda qaysi ish qo‘lda bajariladi?"}, {"id": "legacy-53", "cat": "AI va avtomatlashtirish", "term": "n8n / Make", "sub": "Jarayonlarni avtomatlashtirish", "definition": "Tizimlar orasida qadamlar va ma’lumot almashinuvini tuzish vositalari.\n\nJarayon odatda boshlovchi hodisa va undan keyingi amallardan tuziladi. Tayyor ulanishlar mavjud bo‘lishi mumkin, lekin kerakli funksiya, ruxsat va tarif mosligini tekshirish kerak. Bu vositalar xatolarni kuzatish va qayta urinish tartibini talab qiladi. Sotuvchi sifatida koddan avval qaysi ma’lumot qayerga o‘tishini tushuning.", "example": "Murojaatni CRM’ga uzatib, mas’ulga bildirish.", "group": "ai", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "where": "Kompaniya qaysi avtomatlashtirish vositasidan foydalanadi?"}, {"id": "legacy-54", "cat": "Biznes va boshqaruv", "term": "1C / Odoo / SAP", "sub": "Biznes tizimlari misollari", "definition": "Hisob va biznes boshqaruviga oid turli mahsulotlar; imkoniyatlar versiya va modullarga bog‘liq.\n\nBu nomlar bitta bir xil funksiyali dastur emas; turli mahsulot, modul va joriy qilish shakllari mavjud. Mijoz ishlatayotgan aniq mahsulot va versiyani so‘rang. Nima yaxshi ishlayotgani va qaysi ehtiyoj qoplanmayotganini aniqlang. Yangi yechim mavjud tizimni to‘ldiradimi yoki almashtiradimi — buni texnik va biznes tahlil belgilaydi.", "example": "Mijozning mavjud tizimidan ma’lumot olish ehtiyojini o‘rganish.", "group": "business", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "where": "Qaysi mahsulot, versiya va modullar ishlatiladi?"}, {"id": "legacy-55", "cat": "IT va dasturlash", "term": "Postman", "sub": "API tekshirish vositasi", "definition": "Texnik jamoa API so‘rov va javoblarini tekshiradi.\n\nVosita API manziliga so‘rov yuborib, javobni tekshirishga yordam beradi. Texnik mutaxassis shu orqali ruxsat, maydonlar va xatolarni o‘rganishi mumkin. Sizdan hozir chuqur foydalanish talab qilinmaydi, lekin vazifasini bilish integratsiya muhokamasini osonlashtiradi. Kalit va tokenlarni mijozlar bilan ochiq yozishmalarda tarqatmang.", "example": "CRM API’ga sinov so‘rovi yuborish.", "group": "it", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "where": "Integratsiyani texnik jamoa tekshirib bera oladimi?"}, {"id": "legacy-56", "cat": "Biznes va boshqaruv", "term": "Uchrashuv vositalari", "sub": "Kalendar va video aloqa", "definition": "Uchrashuv vaqtini kelishish, havola yuborish va ekran ulashish.\n\nKalendar orqali vaqt, qatnashchilar va uchrashuv maqsadi kelishiladi; video aloqada demo ekrani ulashiladi. Taklif havolasi ishlashini va mijozga vaqt tushunarli ekanini tekshiring. Oldindan qisqa kun tartibi yuborish suhbatni samarali qiladi. Uchrashuv oxirida mas’ul, vazifa va keyingi sanani qayd eting.", "example": "Demo uchun sana va qatnashchilarni tasdiqlash.", "group": "business", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "where": "Demoda kimlar ishtirok etadi?"}, {"id": "it-0", "group": "it", "term": "Frontend", "sub": "Foydalanuvchi ko‘radigan qism", "definition": "Sayt yoki ilovaning ekranda ko‘rinadigan va odam ishlatadigan qismi. Tugmalar, shakllar va sahifalar shu yerda quriladi. Chiroyli ko‘rinish bilan birga tushunarli boshqaruv va tez ishlash ham muhim.", "example": "Ota-ona kurs tanlab ariza yuboradigan sahifa frontendga kiradi.", "where": "Amaliy tekshiruv: Ota-ona kurs tanlab ariza yuboradigan sahifa frontendga kiradi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-1", "group": "it", "term": "Backend", "sub": "Dastur ortidagi mantiq", "definition": "So‘rovlarni qayta ishlaydigan, qoidalarni bajaradigan va ma’lumot saqlash bilan ishlaydigan qism. Ekrandagi tugma backendga so‘rov yuborishi mumkin. Frontenddagi yashirishning o‘zi ma’lumotni himoyalamaydi.", "example": "To‘lov yozuvi saqlanishidan oldin foydalanuvchi vakolati backendda tekshiriladi.", "where": "Amaliy tekshiruv: To‘lov yozuvi saqlanishidan oldin foydalanuvchi vakolati backendda tekshiriladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-2", "group": "it", "term": "Database", "sub": "Ma’lumotlar bazasi", "definition": "Ma’lumotlarni tartibli saqlash va topish uchun tizim. Jadvallar yoki boshqa tuzilmalar orqali yozuvlar bog‘lanadi. To‘g‘ri tuzilma takroriy va noto‘g‘ri yozuvlarni kamaytiradi.", "example": "O‘quvchilar, guruhlar va to‘lovlar alohida, lekin bog‘langan jadvallarda saqlanadi.", "where": "Amaliy tekshiruv: O‘quvchilar, guruhlar va to‘lovlar alohida, lekin bog‘langan jadvallarda saqlanadi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-3", "group": "it", "term": "Server", "sub": "So‘rovlarga xizmat qiluvchi tizim", "definition": "Boshqa qurilmalardan kelgan so‘rovlarni qabul qilib javob beradigan dastur yoki kompyuter. Server jismoniy yoki bulutdagi virtual qurilmada ishlashi mumkin. Ishonchlilik uchun kuzatuv va zaxira kerak.", "example": "Sayt kurslar ro‘yxatini serverdan oladi.", "where": "Amaliy tekshiruv: Sayt kurslar ro‘yxatini serverdan oladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-4", "group": "it", "term": "Hosting", "sub": "Saytni joylashtirish xizmati", "definition": "Sayt fayllari yoki server dasturini internet orqali ishlatishga imkon beradigan xizmat. Statik sahifa va murakkab serverli ilova talabi farq qiladi. Hosting narxi bilan domen narxi alohida bo‘lishi mumkin.", "example": "Termin kartochkalari statik hostingda joylashtiriladi.", "where": "Amaliy tekshiruv: Termin kartochkalari statik hostingda joylashtiriladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-5", "group": "it", "term": "Domen", "sub": "Internetdagi nomli manzil", "definition": "Odam eslab qoladigan sayt nomi. DNS bu nomni tegishli xizmat manziliga bog‘laydi. Domen olish saytni avtomatik yaratmaydi va hosting o‘rnini bosmaydi.", "example": "markaz.uz nomi o‘quv markazining saytiga yo‘naltiriladi.", "where": "Amaliy tekshiruv: markaz.uz nomi o‘quv markazining saytiga yo‘naltiriladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-6", "group": "it", "term": "Git", "sub": "O‘zgarishlar tarixini boshqarish", "definition": "Fayllardagi o‘zgarishlarni versiyalar sifatida saqlaydigan vosita. Kim nima o‘zgartirgani va oldingi holatga qaytish imkonini beradi. Gitning o‘zi sayt hosting xizmati emas.", "example": "Yangi test ishlamasa, oldingi kod versiyasi solishtiriladi.", "where": "Amaliy tekshiruv: Yangi test ishlamasa, oldingi kod versiyasi solishtiriladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-7", "group": "it", "term": "Repository", "sub": "Loyiha ombori", "definition": "Kod, fayllar va ularning o‘zgarish tarixi saqlanadigan loyiha joyi. Mahalliy yoki GitHub kabi xizmatda bo‘lishi mumkin. Ochiq omborga maxfiy kalit qo‘yilmaydi.", "example": "Sayt kodi va terminlar ma’lumotlari bir repozitoriyda turadi.", "where": "Amaliy tekshiruv: Sayt kodi va terminlar ma’lumotlari bir repozitoriyda turadi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-8", "group": "it", "term": "Deployment", "sub": "Dastur versiyasini ishga chiqarish", "definition": "Tayyor kodni foydalanuvchilar ishlatadigan muhitga joylashtirish. Sinov muhitida ishlash hali jonli saytga chiqarildi degani emas. Chiqarilgach asosiy funksiyalar tekshiriladi.", "example": "Yangi terminlar qo‘shilgan versiya jonli saytga chiqariladi.", "where": "Amaliy tekshiruv: Yangi terminlar qo‘shilgan versiya jonli saytga chiqariladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-9", "group": "it", "term": "Bug", "sub": "Dastur xatosi", "definition": "Dastur kutilganidan boshqacha ishlaydigan holat. Xatoni tuzatish uchun qadamlar, kutilgan natija va haqiqiy natija yoziladi. Har bir noqulaylik texnik xato bo‘lavermaydi.", "example": "Testda to‘g‘ri javob noto‘g‘ri deb hisoblanmoqda.", "where": "Amaliy tekshiruv: Testda to‘g‘ri javob noto‘g‘ri deb hisoblanmoqda.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-10", "group": "it", "term": "QA", "sub": "Sifatni ta’minlash", "definition": "Mahsulot sifati uchun jarayonlar va tekshiruvlarni tashkil qilish. Testlash uning bir qismi, lekin QA faqat xato topish emas. Talabning aniqligi va xatolarning oldini olish ham kiradi.", "example": "Yangi to‘lov funksiyasi uchun asosiy va chegaraviy holatlar tekshiriladi.", "where": "Amaliy tekshiruv: Yangi to‘lov funksiyasi uchun asosiy va chegaraviy holatlar tekshiriladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "QA sifat jarayonini qamraydi; testlash uning bir qismi.", "cat": "IT va dasturlash"}, {"id": "it-11", "group": "it", "term": "Authentication", "sub": "Kimlikni tekshirish", "definition": "Tizimga kirayotgan foydalanuvchi kimligini tekshirish. Parol yoki boshqa usul qo‘llanadi. Kimligini bilish barcha ma’lumotga ruxsat berildi degani emas.", "example": "O‘qituvchi o‘z akkaunti orqali tizimga kiradi.", "where": "Amaliy tekshiruv: O‘qituvchi o‘z akkaunti orqali tizimga kiradi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "Autentifikatsiya kimlikni, avtorizatsiya vakolatni tekshiradi.", "cat": "IT va dasturlash"}, {"id": "it-12", "group": "it", "term": "Authorization", "sub": "Vakolatni tekshirish", "definition": "Tasdiqlangan foydalanuvchi qaysi amalni bajara olishini tekshirish. Huquqlar rol va vazifaga qarab beriladi. Bu autentifikatsiyadan farq qiladi.", "example": "O‘qituvchi davomatni belgilaydi, lekin kassa hisobotini o‘zgartira olmaydi.", "where": "Amaliy tekshiruv: O‘qituvchi davomatni belgilaydi, lekin kassa hisobotini o‘zgartira olmaydi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "Tizimga kirish huquqi barcha amallarni bajarish vakolati emas.", "cat": "IT va dasturlash"}, {"id": "it-13", "group": "it", "term": "Backup", "sub": "Zaxira nusxa", "definition": "Asosiy ma’lumot yo‘qolsa tiklash uchun saqlanadigan nusxa. Nusxa olish bilan birga undan tiklashni ham sinash kerak. Oddiy sinxronlash barcha holatda zaxira o‘rnini bosmaydi.", "example": "To‘lov bazasining zaxirasidan sinov muhitida tiklash tekshiriladi.", "where": "Amaliy tekshiruv: To‘lov bazasining zaxirasidan sinov muhitida tiklash tekshiriladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "it-14", "group": "it", "term": "Version", "sub": "Versiya", "definition": "Mahsulotning ma’lum holatdagi nashri. Versiya raqami va o‘zgarish qaydi yangiliklarni kuzatishga yordam beradi. Kichik tuzatish va katta yangilanish ajratilishi mumkin.", "example": "TerminLab 1.1 versiyasida yangi soha qo‘shiladi.", "where": "Amaliy tekshiruv: TerminLab 1.1 versiyasida yangi soha qo‘shiladi.", "related": ["legacy-28", "legacy-29", "legacy-30"], "confusion": "", "cat": "IT va dasturlash"}, {"id": "ai-0", "group": "ai", "term": "Machine learning", "sub": "Mashinaviy o‘rganish", "definition": "Ma’lumotlardan qonuniyatlarni o‘rganib bashorat yoki tasnif qiladigan usullar. Har bir qoida dasturchi tomonidan alohida yozilmaydi. Natija o‘quv ma’lumotlari sifati va vazifaga bog‘liq.", "example": "Oldingi savdolar asosida keyingi haftadagi talab bashorat qilinadi.", "where": "Amaliy tekshiruv: Oldingi savdolar asosida keyingi haftadagi talab bashorat qilinadi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-1", "group": "ai", "term": "Generative AI", "sub": "Yangi kontent yaratuvchi AI", "definition": "Matn, rasm yoki boshqa kontent yaratadigan modellar. Ular o‘rgangan naqshlar asosida javob beradi. Ravon javobning o‘zi fakt to‘g‘riligini isbotlamaydi.", "example": "Yordamchi kurs haqida javob loyihasini yozadi, narx esa tasdiqlangan bazadan olinadi.", "where": "Amaliy tekshiruv: Yordamchi kurs haqida javob loyihasini yozadi, narx esa tasdiqlangan bazadan olinadi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-2", "group": "ai", "term": "Chatbot", "sub": "Suhbat yordamchisi", "definition": "Xabar orqali foydalanuvchi bilan muloqot qiladigan dastur. Qoidalar yoki AI asosida ishlashi mumkin. Har bir chatbot tashqi tizimda amal bajaradigan agent emas.", "example": "Bot ish vaqti va manzil haqidagi savolga javob beradi.", "where": "Amaliy tekshiruv: Bot ish vaqti va manzil haqidagi savolga javob beradi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-3", "group": "ai", "term": "Context window", "sub": "Model ko‘ra oladigan kontekst", "definition": "Model bitta so‘rovda qayta ishlay oladigan matn hajmi chegarasi. Suhbat tarixi va hujjatlar ham bu hajmga kiradi. Katta kontekst barcha ma’lumotni to‘g‘ri tushunishni kafolatlamaydi.", "example": "Uzun suhbatning eski qismi qisqa xulosaga almashtiriladi.", "where": "Amaliy tekshiruv: Uzun suhbatning eski qismi qisqa xulosaga almashtiriladi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-4", "group": "ai", "term": "Embedding", "sub": "Ma’noni sonlar bilan ifodalash", "definition": "Matn yoki boshqa ma’lumotni sonli vektorga aylantirish. O‘xshash mazmunli matnlarni topishga yordam beradi. Bu so‘zlarni oddiy alfavit bo‘yicha qidirishdan farq qiladi.", "example": "Bolalar uchun til kursi savoliga mazmunan yaqin kurs tavsifi topiladi.", "where": "Amaliy tekshiruv: Bolalar uchun til kursi savoliga mazmunan yaqin kurs tavsifi topiladi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-5", "group": "ai", "term": "Vector database", "sub": "Vektorlar bazasi", "definition": "Embeddinglarni saqlab, o‘xshashlik bo‘yicha qidiradigan tizim. Bilim bazasidagi mos parchalarga yetishish uchun ishlatilishi mumkin. Topilgan hujjatning dolzarbligi alohida tekshiriladi.", "example": "Agent savolga mos qoida yoki kurs tavsifini qidiradi.", "where": "Amaliy tekshiruv: Agent savolga mos qoida yoki kurs tavsifini qidiradi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-6", "group": "ai", "term": "Fine-tuning", "sub": "Modelni qo‘shimcha moslashtirish", "definition": "Oldindan o‘qitilgan modelni maxsus misollar bilan qo‘shimcha o‘qitish. Uslub yoki vazifaga moslashishga xizmat qilishi mumkin. Tez-tez o‘zgaradigan narxlarni saqlash uchun odatda baza bilan ulash qulayroq.", "example": "Javob formatini bir xil qilish uchun namunalar bilan model moslashtiriladi.", "where": "Amaliy tekshiruv: Javob formatini bir xil qilish uchun namunalar bilan model moslashtiriladi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-7", "group": "ai", "term": "Inference", "sub": "Modeldan natija olish", "definition": "Tayyor modelga kirish berib javob yoki bashorat olish jarayoni. Bu modelni o‘qitishdan boshqa bosqich. Tezlik va foydalanish xarajati shu jarayonda ham muhim.", "example": "Ota-onaning savoli modelga yuborilib javob olinadi.", "where": "Amaliy tekshiruv: Ota-onaning savoli modelga yuborilib javob olinadi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-8", "group": "ai", "term": "Tool calling", "sub": "Vosita chaqirish", "definition": "Model tashqi funksiyani chaqirish uchun tuzilgan so‘rov tayyorlaydi. Funksiyani dastur bajaradi va natijani qaytaradi. Amal bajarilishidan oldin ruxsat va parametrlar tekshiriladi.", "example": "Agent bo‘sh sinov vaqtlarini jadvaldan so‘raydi.", "where": "Amaliy tekshiruv: Agent bo‘sh sinov vaqtlarini jadvaldan so‘raydi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-9", "group": "ai", "term": "Guardrails", "sub": "Chegara va himoya qoidalari", "definition": "Agentning qanday javob va amallarni bajarishini cheklovchi tekshiruvlar. Faqat ko‘rsatma yozish bilan cheklanmaydi; dasturiy nazorat ham kerak. Xavfni kamaytiradi, mutlaq kafolat bermaydi.", "example": "Tasdiqlanmagan chegirma yoki begona o‘quvchi ma’lumoti berilmaydi.", "where": "Amaliy tekshiruv: Tasdiqlanmagan chegirma yoki begona o‘quvchi ma’lumoti berilmaydi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-10", "group": "ai", "term": "AI evaluation", "sub": "AI javoblarini baholash", "definition": "Agentni oldindan tuzilgan savollar va mezonlar bilan sinash. To‘g‘rilik, foydalilik va xodimga topshirish kabi jihatlar o‘lchanadi. Bitta chiroyli demo yetarli dalil emas.", "example": "100 ta namunaviy savolda noto‘g‘ri narx aytish holatlari sanaladi.", "where": "Amaliy tekshiruv: 100 ta namunaviy savolda noto‘g‘ri narx aytish holatlari sanaladi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-11", "group": "ai", "term": "Trigger", "sub": "Jarayonni boshlovchi hodisa", "definition": "Avtomatik jarayon qachon ishga tushishini bildiradigan shart yoki hodisa. Xabar kelishi, vaqt yetishi yoki yozuv o‘zgarishi bo‘lishi mumkin. Takroriy hodisalar nazorat qilinadi.", "example": "Telegram xabari kelganda javob jarayoni boshlanadi.", "where": "Amaliy tekshiruv: Telegram xabari kelganda javob jarayoni boshlanadi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-12", "group": "ai", "term": "Condition", "sub": "Jarayondagi shart", "definition": "Ma’lumotga qarab qaysi yo‘ldan davom etishni belgilovchi qoida. AI ishlatmasdan ham aniq shartlarni tekshirish mumkin. Shart noto‘g‘ri bo‘lsa jarayon noto‘g‘ri tarmoqqa o‘tadi.", "example": "Yosh 10 dan kichik bo‘lsa bolalar guruhi variantlari olinadi.", "where": "Amaliy tekshiruv: Yosh 10 dan kichik bo‘lsa bolalar guruhi variantlari olinadi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-13", "group": "ai", "term": "Retry", "sub": "Qayta urinish", "definition": "Vaqtinchalik xatodan keyin amalni yana bajarish. Urinishlar soni va kutish vaqti cheklanadi. Pul yoki yozuv yaratadigan amallar takrorlanib ketmasligi kerak.", "example": "Xabar yuborish xizmati vaqtincha ishlamasa keyin qayta uriniladi.", "where": "Amaliy tekshiruv: Xabar yuborish xizmati vaqtincha ishlamasa keyin qayta uriniladi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "ai-14", "group": "ai", "term": "Idempotency", "sub": "Takroriy so‘rovda bir xil natija", "definition": "Bir amal qayta yuborilganda ortiqcha yozuv yoki to‘lov hosil qilmaslik xususiyati. Maxsus kalit yoki tekshiruv bilan ta’minlanadi. Ishonchli avtomatlashtirishda muhim.", "example": "Bir ariza ikki marta kelganda bitta band qilish saqlanadi.", "where": "Amaliy tekshiruv: Bir ariza ikki marta kelganda bitta band qilish saqlanadi.", "related": ["legacy-3", "legacy-19", "legacy-38"], "confusion": "", "cat": "AI va avtomatlashtirish"}, {"id": "data-0", "group": "data", "term": "SQL", "sub": "Ma’lumotlar bilan ishlash tili", "definition": "Ko‘pincha relyatsion bazalarda ma’lumot olish va o‘zgartirish uchun ishlatiladi. So‘rov natijasi filtr va bog‘lash qoidalariga bog‘liq. To‘g‘ri sintaksis noto‘g‘ri biznes hisobini ham chiqarishi mumkin.", "example": "Filial bo‘yicha oy davomida to‘lagan o‘quvchilar soni olinadi.", "where": "Amaliy tekshiruv: Filial bo‘yicha oy davomida to‘lagan o‘quvchilar soni olinadi.", "related": ["legacy-26", "legacy-52", "data-1"], "confusion": "", "cat": "Data analitika"}, {"id": "data-1", "group": "data", "term": "Power BI", "sub": "Hisobot va tahlil vositasi", "definition": "Ma’lumotlarni ulash, model tuzish va interaktiv hisobot yaratishga yordam beradi. Hisobotdan oldin ma’lumotning sifati tekshiriladi. Chiroyli grafik noto‘g‘ri hisobni tuzatmaydi.", "example": "Rahbar 4 filial tushumini bitta hisobotda ko‘radi.", "where": "Amaliy tekshiruv: Rahbar 4 filial tushumini bitta hisobotda ko‘radi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-2", "group": "data", "term": "ETL", "sub": "Olish, o‘zgartirish, yuklash", "definition": "Ma’lumotni manbadan olish, kerakli formatga keltirish va maqsad tizimiga yuklash jarayoni. Turli fayllarni birlashtirishda qo‘llanadi. Xato va takrorlar jarayon davomida nazorat qilinadi.", "example": "Filial Excel fayllari tozalanib umumiy bazaga yuklanadi.", "where": "Amaliy tekshiruv: Filial Excel fayllari tozalanib umumiy bazaga yuklanadi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-3", "group": "data", "term": "Data cleaning", "sub": "Ma’lumotni tozalash", "definition": "Takror, bo‘sh qiymat, format va mantiqiy xatolarni tekshirib tuzatish. O‘chirishdan oldin xatoning sababi aniqlanadi. Tozalash qoidalari qayd etilishi kerak.", "example": "Toshkent va tashkent yozuvlari yagona shaklga keltiriladi.", "where": "Amaliy tekshiruv: Toshkent va tashkent yozuvlari yagona shaklga keltiriladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-4", "group": "data", "term": "Data quality", "sub": "Ma’lumot sifati", "definition": "Ma’lumotning aniqlik, to‘liqlik, dolzarblik va izchillik kabi xususiyatlari. Sifat vazifaga mos baholanadi. Yetishmagan ma’lumotdan ortiqcha xulosa chiqarilmaydi.", "example": "Tug‘ilgan sana noto‘g‘ri bo‘lsa yoshga qarab guruh tavsiyasi xato chiqadi.", "where": "Amaliy tekshiruv: Tug‘ilgan sana noto‘g‘ri bo‘lsa yoshga qarab guruh tavsiyasi xato chiqadi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-5", "group": "data", "term": "Mean", "sub": "Arifmetik o‘rtacha", "definition": "Qiymatlar yig‘indisini ularning soniga bo‘lish orqali hisoblanadi. Juda katta yoki kichik qiymatlar o‘rtachaga kuchli ta’sir qilishi mumkin. Tarqalish bilan birga qarash foydali.", "example": "5 ta xarid summasi qo‘shilib 5 ga bo‘linadi.", "where": "Amaliy tekshiruv: 5 ta xarid summasi qo‘shilib 5 ga bo‘linadi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-6", "group": "data", "term": "Median", "sub": "Tartiblangan qator o‘rtasi", "definition": "Qiymatlar tartiblanganda o‘rtadagi qiymat; soni juft bo‘lsa ikki o‘rta qiymat o‘rtachasi. Keskin katta qiymatlarga o‘rtachadan kamroq sezgir. Odatdagi holatni tasvirlashga yordam beradi.", "example": "Bitta juda yuqori maosh bo‘lsa odatiy maosh median bilan ko‘rsatiladi.", "where": "Amaliy tekshiruv: Bitta juda yuqori maosh bo‘lsa odatiy maosh median bilan ko‘rsatiladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-7", "group": "data", "term": "Outlier", "sub": "Keskin farq qiluvchi qiymat", "definition": "Boshqa kuzatuvlardan ancha farq qiladigan qiymat. Xato ham, haqiqiy noodatiy holat ham bo‘lishi mumkin. Sababini tekshirmasdan o‘chirib yuborilmaydi.", "example": "Yosh ustunidagi 200 qiymati manba bilan tekshiriladi.", "where": "Amaliy tekshiruv: Yosh ustunidagi 200 qiymati manba bilan tekshiriladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-8", "group": "data", "term": "Correlation", "sub": "Birga o‘zgarish bog‘liqligi", "definition": "Ikki ko‘rsatkichning birga o‘zgarishini ifodalaydi. Bog‘liqlik birining ikkinchisiga sabab bo‘lganini isbotlamaydi. Boshqa omillar ham ta’sir qilishi mumkin.", "example": "Reklama xarajati va sotuv birga oshdi, lekin mavsum ham o‘zgargan.", "where": "Amaliy tekshiruv: Reklama xarajati va sotuv birga oshdi, lekin mavsum ham o‘zgargan.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "Birga o‘zgarish sababiy bog‘liqlikni isbotlamaydi.", "cat": "Data analitika"}, {"id": "data-9", "group": "data", "term": "A/B test", "sub": "Ikki variantni tajribada solishtirish", "definition": "O‘xshash foydalanuvchilar guruhlariga turli variant ko‘rsatib natijani taqqoslash. Mezon va davomiylik oldindan belgilanadi. Oz kuzatuv asosida shoshilinch g‘olib tanlanmaydi.", "example": "Ikki ariza sahifasining ro‘yxatdan o‘tish natijasi solishtiriladi.", "where": "Amaliy tekshiruv: Ikki ariza sahifasining ro‘yxatdan o‘tish natijasi solishtiriladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-10", "group": "data", "term": "Cohort", "sub": "Umumiy belgili guruh", "definition": "Bir davrda yoki bir hodisa orqali kelgan odamlar guruhi. Ularning keyingi harakati vaqt bo‘yicha kuzatiladi. Turli davrlarni aralashtirish xulosani chalkashtirishi mumkin.", "example": "Sentabrda kelgan o‘quvchilarning 3 oy davomida qolishi kuzatiladi.", "where": "Amaliy tekshiruv: Sentabrda kelgan o‘quvchilarning 3 oy davomida qolishi kuzatiladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-11", "group": "data", "term": "Retention", "sub": "Foydalanuvchining davom etishi", "definition": "Boshlang‘ich guruhdan ma’lum vaqt o‘tib xizmatdan foydalanayotganlar ulushi. Qaytish yoki faol bo‘lish mezoni aniq belgilanadi. Har tashkilotning hisoblash usuli bir xil emas.", "example": "Oy boshidagi 100 o‘quvchidan 85 tasi keyingi oy davom etdi.", "where": "Amaliy tekshiruv: Oy boshidagi 100 o‘quvchidan 85 tasi keyingi oy davom etdi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-12", "group": "data", "term": "Churn", "sub": "Ketib qolish", "definition": "Belgilangan davrda xizmatdan foydalanishni to‘xtatgan mijozlar ulushi. Kim ketgan deb hisoblanishi oldindan belgilanadi. Tanaffus va doimiy ketishni farqlash zarur.", "example": "Kursni tark etganlar sababi va ulushi oyma-oy kuzatiladi.", "where": "Amaliy tekshiruv: Kursni tark etganlar sababi va ulushi oyma-oy kuzatiladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-13", "group": "data", "term": "JOIN", "sub": "Jadvallarni bog‘lash", "definition": "SQLda mos ustunlar orqali jadvallardagi ma’lumotlarni birlashtirish. Bog‘lanish turi qaysi qatorlar qolishini belgilaydi. Birga-ko‘p bog‘lanish summalarni takrorlab yuborishi mumkin.", "example": "O‘quvchi jadvali to‘lovlar bilan identifikator orqali bog‘lanadi.", "where": "Amaliy tekshiruv: O‘quvchi jadvali to‘lovlar bilan identifikator orqali bog‘lanadi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "data-14", "group": "data", "term": "Primary key", "sub": "Yozuvning noyob kaliti", "definition": "Jadvaldagi har qatorni yagona aniqlaydigan ustun yoki ustunlar to‘plami. Takrorlanmasligi va bo‘sh bo‘lmasligi kerak. Ism ko‘pincha noyob kalit bo‘la olmaydi.", "example": "Bir xil ismli ikki o‘quvchining ID raqami boshqa bo‘ladi.", "where": "Amaliy tekshiruv: Bir xil ismli ikki o‘quvchining ID raqami boshqa bo‘ladi.", "related": ["legacy-26", "legacy-52", "data-0"], "confusion": "", "cat": "Data analitika"}, {"id": "sales-0", "group": "sales", "term": "B2C", "sub": "Biznesdan shaxsga savdo", "definition": "Mahsulot yoki xizmat yakuniy iste’molchiga sotiladi. Xarid sababi, qaror va aloqa usuli B2Bdan farq qilishi mumkin. Har bir B2C xarid tez yoki arzon bo‘lavermaydi.", "example": "O‘quv markazi ota-onaga farzandi uchun kurs sotadi.", "where": "Amaliy tekshiruv: O‘quv markazi ota-onaga farzandi uchun kurs sotadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-1", "group": "sales", "term": "ICP", "sub": "Ideal mijoz profili", "definition": "Taklifdan eng ko‘p foyda olishi mumkin bo‘lgan mijoz turi tavsifi. Sohasi, hajmi va muammosi kabi belgilar kiritiladi. Bu bitta shaxsning to‘liq tarjimai holi emas.", "example": "Ko‘p murojaat oladigan, javob berishga ulgurmaydigan markaz AI administrator uchun mos profil.", "where": "Amaliy tekshiruv: Ko‘p murojaat oladigan, javob berishga ulgurmaydigan markaz AI administrator uchun mos profil.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-2", "group": "sales", "term": "Value proposition", "sub": "Qiymat taklifi", "definition": "Mijozga qanday foyda va nima sababdan sizni tanlash kerakligini tushuntiradi. Funksiyalar ro‘yxatidan ko‘ra muammo va natijaga bog‘lanadi. Dalilsiz katta va’da berilmaydi.", "example": "Javobsiz murojaatlarni yig‘ib, administratorga tayyor xulosa berish taklif qilinadi.", "where": "Amaliy tekshiruv: Javobsiz murojaatlarni yig‘ib, administratorga tayyor xulosa berish taklif qilinadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-3", "group": "sales", "term": "Qualification criteria", "sub": "Moslik mezonlari", "definition": "Lidni davom ettirishga arziydimi degan qaror uchun belgilar. Ehtiyoj, xizmatga moslik, qaror jarayoni va vaqt baholanadi. Faqat budjetni so‘rash bilan cheklanmaydi.", "example": "Haqiqiy biznesi va avtomatlashtirish ehtiyoji borligi aniqlanadi.", "where": "Amaliy tekshiruv: Haqiqiy biznesi va avtomatlashtirish ehtiyoji borligi aniqlanadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-4", "group": "sales", "term": "Sales cycle", "sub": "Sotuv davri", "definition": "Dastlabki aloqadan yakuniy qarorgacha bo‘lgan jarayon va vaqt. Murakkab xaridda bir necha uchrashuv bo‘lishi mumkin. Davr uzunligi mahsulot va mijozga bog‘liq.", "example": "ERP uchun suhbat, demo, taklif va shartnoma ketma-ket o‘tadi.", "where": "Amaliy tekshiruv: ERP uchun suhbat, demo, taklif va shartnoma ketma-ket o‘tadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-5", "group": "sales", "term": "Closing", "sub": "Kelishuvni yakunlash", "definition": "Tomonlar shartlarni aniqlab xaridning keyingi rasmiy qadamiga kelishadi. Mijozni bosim bilan rozi qilish degani emas. Og‘zaki qiziqish to‘lov yoki shartnoma bilan teng emas.", "example": "Mijoz taklifni ma’qullab shartnoma imzolash sanasini kelishadi.", "where": "Amaliy tekshiruv: Mijoz taklifni ma’qullab shartnoma imzolash sanasini kelishadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-6", "group": "sales", "term": "Upsell", "sub": "Kengroq variantni taklif qilish", "definition": "Mijoz ehtiyojiga mos kattaroq yoki yuqoriroq imkoniyatli variantni taklif qilish. Qo‘shimcha qiymat tushuntirilishi kerak. Keraksiz qimmat paketni majburlash foydali emas.", "example": "Bitta filial pilotidan so‘ng 4 filialga kengaytirish taklif qilinadi.", "where": "Amaliy tekshiruv: Bitta filial pilotidan so‘ng 4 filialga kengaytirish taklif qilinadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-7", "group": "sales", "term": "Cross-sell", "sub": "Bog‘liq xizmatni taklif qilish", "definition": "Asosiy xaridga mos boshqa mahsulot yoki xizmat tavsiya qilinadi. Tavsiya ehtiyojga bog‘lanadi. Upsell bilan farqi yangi bog‘liq mahsulot qo‘shilishidir.", "example": "CRM olgan mijozga ma’lumot ko‘chirish xizmati taklif qilinadi.", "where": "Amaliy tekshiruv: CRM olgan mijozga ma’lumot ko‘chirish xizmati taklif qilinadi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-8", "group": "sales", "term": "Average order value", "sub": "O‘rtacha xarid summasi", "definition": "Bir davrdagi savdo summasini buyurtmalar soniga bo‘lish. Qaysi bekor va qaytarilgan buyurtmalar chiqarilishi aniqlanadi. Bu foyda ko‘rsatkichi emas.", "example": "10 buyurtmada 2 mln tushum bo‘lsa o‘rtacha buyurtma 200 ming.", "where": "Amaliy tekshiruv: 10 buyurtmada 2 mln tushum bo‘lsa o‘rtacha buyurtma 200 ming.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-9", "group": "sales", "term": "Negotiation", "sub": "Muzokara", "definition": "Tomonlar narx, hajm, muddat va mas’uliyatni kelishadigan suhbat. Faqat chegirma so‘rashdan kengroq tushuncha. O‘zgarishlar yakuniy taklifda qayd etiladi.", "example": "Narxni tushirish o‘rniga birinchi bosqichdagi funksiyalar qisqartiriladi.", "where": "Amaliy tekshiruv: Narxni tushirish o‘rniga birinchi bosqichdagi funksiyalar qisqartiriladi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-10", "group": "sales", "term": "Buying signal", "sub": "Xaridga qiziqish belgisi", "definition": "Mijozning keyingi qadamni jiddiy ko‘rayotganini ko‘rsatuvchi savol yoki harakat. Belgilar xarid kafolati emas. Aniq keyingi qadam bilan tekshiriladi.", "example": "Mijoz o‘rnatish sanasi va shartnoma tartibini so‘raydi.", "where": "Amaliy tekshiruv: Mijoz o‘rnatish sanasi va shartnoma tartibini so‘raydi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-11", "group": "sales", "term": "Account manager", "sub": "Mijoz bilan aloqalar mas’uli", "definition": "Mavjud mijozning ehtiyojlari va kompaniya bilan hamkorligini yuritadi. Texnik va boshqa jamoalar bilan muvofiqlashtiradi. Har masalani o‘zi texnik hal qilishi shart emas.", "example": "Mijozning yangi filial ulash talabi jamoaga yetkaziladi.", "where": "Amaliy tekshiruv: Mijozning yangi filial ulash talabi jamoaga yetkaziladi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-12", "group": "sales", "term": "Customer success", "sub": "Mijozning natijaga erishishi", "definition": "Mijoz sotib olgan xizmatdan kutilgan foydani olishiga yordam berish. O‘rgatish, foydalanish va to‘siqlarni bartaraf etish kiradi. Faqat shikoyatga javob berish emas.", "example": "CRM sotilgach xodimlar undan to‘g‘ri foydalanishi kuzatiladi.", "where": "Amaliy tekshiruv: CRM sotilgach xodimlar undan to‘g‘ri foydalanishi kuzatiladi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-13", "group": "sales", "term": "Referral", "sub": "Tavsiya orqali murojaat", "definition": "Mavjud mijoz yoki tanish tavsiyasi bilan yangi odam kelishi. Manbani qayd qilish bu kanalni baholashga yordam beradi. Tavsiya kelgani avtomatik xarid degani emas.", "example": "Bir markaz rahbari xizmatni boshqa markazga tavsiya qiladi.", "where": "Amaliy tekshiruv: Bir markaz rahbari xizmatni boshqa markazga tavsiya qiladi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "sales-14", "group": "sales", "term": "Lost reason", "sub": "Sotuv bo‘lmaganining sababi", "definition": "Yakunlanmagan kelishuvning qayd etilgan sababi. Taxmin emas, mijoz javobi va aniqlangan holat yoziladi. Sabablar mahsulot va savdo jarayonini yaxshilashga yordam beradi.", "example": "Mijoz loyiha muddatini keyingi yilga surganini aytdi.", "where": "Amaliy tekshiruv: Mijoz loyiha muddatini keyingi yilga surganini aytdi.", "related": ["legacy-0", "legacy-4", "legacy-6"], "confusion": "", "cat": "Savdo va mijozlar"}, {"id": "marketing-0", "group": "marketing", "term": "Target audience", "sub": "Maqsadli auditoriya", "definition": "Mahsulot yoki xabar mo‘ljallangan odamlar guruhi. Ehtiyoj, hudud va boshqa tegishli belgilar bilan aniqlanadi. Reklama ko‘rgan hamma odam mijozga mos emas.", "example": "Bolalar kursi reklamasi tegishli hududdagi ota-onalarga mo‘ljallanadi.", "where": "Amaliy tekshiruv: Bolalar kursi reklamasi tegishli hududdagi ota-onalarga mo‘ljallanadi.", "related": ["marketing-1", "marketing-2", "marketing-3"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-1", "group": "marketing", "term": "Segmentation", "sub": "Auditoriyani guruhlash", "definition": "Auditoriyani ehtiyoj yoki xatti-harakat bo‘yicha kichik guruhlarga ajratish. Har guruhga mos xabar tayyorlanadi. Juda ko‘p kichik guruh natijani baholashni qiyinlashtirishi mumkin.", "example": "Bolalar ingliz tili va kattalar kursiga alohida taklif yoziladi.", "where": "Amaliy tekshiruv: Bolalar ingliz tili va kattalar kursiga alohida taklif yoziladi.", "related": ["marketing-0", "marketing-2", "marketing-3"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-2", "group": "marketing", "term": "Positioning", "sub": "Bozorda o‘rnini belgilash", "definition": "Mijoz ongida brend nimasi bilan ajralishini aniq ko‘rsatish. Auditoriya, foyda va farq bir-biriga mos bo‘lishi kerak. Shiorning o‘zi pozitsiyalash emas.", "example": "Markaz o‘zini kichik guruh va muntazam ota-ona hisoboti bilan tanishtiradi.", "where": "Amaliy tekshiruv: Markaz o‘zini kichik guruh va muntazam ota-ona hisoboti bilan tanishtiradi.", "related": ["marketing-0", "marketing-1", "marketing-3"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-3", "group": "marketing", "term": "Reach", "sub": "Qamrov", "definition": "Kontentni ko‘rgan noyob odam yoki akkauntlar soni. Platformadagi hisoblash usuliga bog‘liq. Ko‘rishlar soni bilan bir xil emas.", "example": "Bir odam reklama uch marta ko‘rsa qamrovda odatda bir akkaunt sanaladi.", "where": "Amaliy tekshiruv: Bir odam reklama uch marta ko‘rsa qamrovda odatda bir akkaunt sanaladi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-4", "group": "marketing", "term": "Impressions", "sub": "Ko‘rsatilishlar", "definition": "Kontent yoki reklama necha marta ko‘rsatilganini bildiradi. Bitta odamning bir necha ko‘rishi kirishi mumkin. Ko‘rsatilish xarid yoki bosish degani emas.", "example": "Reklama 100 kishiga jami 250 marta ko‘rsatildi.", "where": "Amaliy tekshiruv: Reklama 100 kishiga jami 250 marta ko‘rsatildi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-5", "group": "marketing", "term": "CTR", "sub": "Bosishlar ulushi", "definition": "Bosishlar sonining ko‘rsatilishlarga nisbati. Odatda foizda ifodalanadi. Qaysi turdagi bosish olinayotgani aniqlanmasa taqqoslash noto‘g‘ri bo‘ladi.", "example": "1000 ko‘rsatilishda 20 havola bosilishi CTRni 2 foiz qiladi.", "where": "Amaliy tekshiruv: 1000 ko‘rsatilishda 20 havola bosilishi CTRni 2 foiz qiladi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-6", "group": "marketing", "term": "CPC", "sub": "Bir bosish xarajati", "definition": "Reklama xarajatining tegishli bosishlar soniga nisbati. Arzon bosish sifatli mijozni kafolatlamaydi. Keyingi bosqich natijasi ham tekshiriladi.", "example": "100 ming xarajat va 50 bosish bo‘lsa CPC 2 ming.", "where": "Amaliy tekshiruv: 100 ming xarajat va 50 bosish bo‘lsa CPC 2 ming.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-7", "group": "marketing", "term": "CPM", "sub": "Ming ko‘rsatilish xarajati", "definition": "Reklama xarajatini ming ko‘rsatilishga nisbatan ifodalaydi. Auditoriya va reklama joyi ta’sir qiladi. Faqat CPM bilan sotuv samarasi baholanmaydi.", "example": "200 ming xarajat va 20 ming ko‘rsatilishda CPM 10 ming.", "where": "Amaliy tekshiruv: 200 ming xarajat va 20 ming ko‘rsatilishda CPM 10 ming.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-8", "group": "marketing", "term": "CPL", "sub": "Bir lid xarajati", "definition": "Reklama xarajatini kelgan lidlar soniga bo‘lish. Lidning sifati va ta’rifi muhim. Tasodifiy arizalar ko‘p bo‘lsa past CPL yaxshi natija bo‘lmasligi mumkin.", "example": "300 ming xarajatdan 30 ariza olindi: CPL 10 ming.", "where": "Amaliy tekshiruv: 300 ming xarajatdan 30 ariza olindi: CPL 10 ming.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-9", "group": "marketing", "term": "CAC", "sub": "Yangi mijozni jalb qilish xarajati", "definition": "Belgilangan jalb qilish xarajatlarini yangi mijozlar soniga bo‘lish. Reklama, sotuv mehnati kabi bandlar usulga qarab kiritiladi. CPLdan farqli ravishda xarid qilgan mijoz hisoblanadi.", "example": "2 mln jalb qilish xarajatidan 10 yangi to‘lovchi olindi.", "where": "Amaliy tekshiruv: 2 mln jalb qilish xarajatidan 10 yangi to‘lovchi olindi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-10", "group": "marketing", "term": "ROAS", "sub": "Reklama xarajatiga nisbatan savdo", "definition": "Reklamaga tegishli savdo summasini reklama xarajatiga bo‘lish. Natija xarajatdan necha baravar savdo kelganini ko‘rsatadi. Bu sof foyda yoki ROI bilan teng emas.", "example": "1 mln reklama 4 mln savdo keltirsa ROAS 4 baravar.", "where": "Amaliy tekshiruv: 1 mln reklama 4 mln savdo keltirsa ROAS 4 baravar.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "ROAS savdo summasiga qaraydi; sof foydani ko‘rsatmaydi.", "cat": "Marketing va SMM"}, {"id": "marketing-11", "group": "marketing", "term": "Content plan", "sub": "Kontent rejasi", "definition": "Qachon, kim uchun va qanday maqsadda kontent chiqarilishini rejalash. Faqat sanalar jadvali emas, xabar va natija ham belgilanadi. Reja natijaga qarab yangilanadi.", "example": "Haftada kurs tanlash, o‘quvchi natijasi va test postlari chiqadi.", "where": "Amaliy tekshiruv: Haftada kurs tanlash, o‘quvchi natijasi va test postlari chiqadi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-12", "group": "marketing", "term": "CTA", "sub": "Harakatga chaqiriq", "definition": "Foydalanuvchiga keyingi qadamni aniq ko‘rsatadigan matn yoki tugma. Harakat taklifga mos bo‘lishi kerak. Bir joyda ko‘p raqobatlashuvchi chaqiriq chalkashtirishi mumkin.", "example": "Sinov darsiga yozilish tugmasi beriladi.", "where": "Amaliy tekshiruv: Sinov darsiga yozilish tugmasi beriladi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-13", "group": "marketing", "term": "Landing page", "sub": "Maqsadli sahifa", "definition": "Muayyan taklif va harakat uchun tuzilgan sahifa. Reklama xabari bilan mazmuni mos bo‘lishi kerak. Oddiy bosh sahifadan ko‘ra bitta vazifaga yo‘naltiriladi.", "example": "Matematika kursi reklamasi shu kurs haqidagi ariza sahifasiga olib boradi.", "where": "Amaliy tekshiruv: Matematika kursi reklamasi shu kurs haqidagi ariza sahifasiga olib boradi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "marketing-14", "group": "marketing", "term": "UTM", "sub": "Havoladagi manba belgilari", "definition": "Havolaga qo‘shilib trafikning manbasi va kampaniyasini ajratadigan parametrlar. Belgilar yagona tartibda yoziladi. Ularning o‘zi barcha xaridni aniq bog‘lab bermaydi.", "example": "Telegram postidan va Instagram reklamadan kelgan tashriflar ajratiladi.", "where": "Amaliy tekshiruv: Telegram postidan va Instagram reklamadan kelgan tashriflar ajratiladi.", "related": ["marketing-0", "marketing-1", "marketing-2"], "confusion": "", "cat": "Marketing va SMM"}, {"id": "business-0", "group": "business", "term": "Strategy", "sub": "Strategiya", "definition": "Uzoqroq muddatdagi maqsad va unga erishish uchun tanlovlar. Nimalarga e’tibor berish va nimalarni hozir qilmaslik aniqlanadi. Kundalik vazifalar ro‘yxati strategiyaning o‘zi emas.", "example": "Markaz keyingi yil yangi filialdan oldin mavjud guruhlarni to‘ldirishni tanlaydi.", "where": "Amaliy tekshiruv: Markaz keyingi yil yangi filialdan oldin mavjud guruhlarni to‘ldirishni tanlaydi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-1", "group": "business", "term": "Mission", "sub": "Faoliyatning asosiy maqsadi", "definition": "Tashkilot kimga va nima uchun xizmat qilishini ifodalaydi. Qarorlar uchun yo‘nalish berishi kerak. Chiroyli matn amaliy ishga mos bo‘lmasa foydasi cheklanadi.", "example": "Markaz bolalarga fanlarni tushunarli va izchil o‘rgatishni maqsad qiladi.", "where": "Amaliy tekshiruv: Markaz bolalarga fanlarni tushunarli va izchil o‘rgatishni maqsad qiladi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-2", "group": "business", "term": "Vision", "sub": "Kelajakdagi holat tasavvuri", "definition": "Tashkilot kelajakda qanday bo‘lishni istashini ko‘rsatadi. Missiyadan farqli ravishda kelajak holatiga qaraydi. Amalga oshirish uchun bosqichlar kerak.", "example": "Markaz hududdagi ishonchli ko‘p filialli ta’lim tarmog‘iga aylanishni ko‘zlaydi.", "where": "Amaliy tekshiruv: Markaz hududdagi ishonchli ko‘p filialli ta’lim tarmog‘iga aylanishni ko‘zlaydi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-3", "group": "business", "term": "OKR", "sub": "Maqsad va asosiy natijalar", "definition": "Maqsadga erishishni o‘lchaydigan natijalar bilan bog‘lash usuli. Natija bajarilgan ish soni emas, erishilgan o‘zgarish bo‘lishi mumkin. KPI bilan vazifasi har doim bir xil emas.", "example": "Javobsiz murojaatlarni kamaytirish maqsadiga aniq o‘lchov belgilanadi.", "where": "Amaliy tekshiruv: Javobsiz murojaatlarni kamaytirish maqsadiga aniq o‘lchov belgilanadi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-4", "group": "business", "term": "SOP", "sub": "Standart ish tartibi", "definition": "Takroriy ishni qanday bajarish haqida yozilgan ketma-ket yo‘riqnoma. Mas’ul va istisnolar ko‘rsatiladi. Jarayon o‘zgarsa hujjat ham yangilanadi.", "example": "Sinovga kelmagan odam bilan qayta aloqa tartibi yoziladi.", "where": "Amaliy tekshiruv: Sinovga kelmagan odam bilan qayta aloqa tartibi yoziladi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-5", "group": "business", "term": "Stakeholder", "sub": "Manfaatdor tomon", "definition": "Loyiha yoki qarordan ta’sirlanadigan yoki unga ta’sir qiladigan shaxs. Faqat rahbar bilan cheklanmaydi. Talablar o‘rtasidagi farq kelishiladi.", "example": "CRM loyihasida administrator, hisobchi va o‘qituvchi manfaatdor tomon.", "where": "Amaliy tekshiruv: CRM loyihasida administrator, hisobchi va o‘qituvchi manfaatdor tomon.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-6", "group": "business", "term": "Bottleneck", "sub": "Jarayondagi tor joy", "definition": "Umumiy ish tezligini cheklaydigan bosqich. Boshqa bosqichlarni tezlatish tor joy o‘zgarmasa yetarli bo‘lmasligi mumkin. Avval yuklama va navbat kuzatiladi.", "example": "Murojaatlar ko‘p, lekin barcha taklifni faqat bir xodim tayyorlaydi.", "where": "Amaliy tekshiruv: Murojaatlar ko‘p, lekin barcha taklifni faqat bir xodim tayyorlaydi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-7", "group": "business", "term": "Delegation", "sub": "Vazifa va vakolat topshirish", "definition": "Ishni kerakli vakolat va mas’uliyat bilan boshqa odamga berish. Natija, muddat va chegaralar aniqlanadi. Faqat ishni aytib qo‘yish yetarli emas.", "example": "Filial administratoriga sinov jadvalini tasdiqlash huquqi beriladi.", "where": "Amaliy tekshiruv: Filial administratoriga sinov jadvalini tasdiqlash huquqi beriladi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-8", "group": "business", "term": "Project", "sub": "Loyiha", "definition": "Muayyan natijaga erishish uchun muddatli ishlar to‘plami. Boshlanish, yakun va ko‘lam belgilanadi. Doimiy kundalik operatsiyadan farq qiladi.", "example": "4 filialga yangi tizim joriy etish loyiha hisoblanadi.", "where": "Amaliy tekshiruv: 4 filialga yangi tizim joriy etish loyiha hisoblanadi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-9", "group": "business", "term": "Milestone", "sub": "Muhim bosqich belgisi", "definition": "Loyihadagi muhim natija yoki nazorat nuqtasi. Har doim bitta kichik vazifa emas. Keyingi bosqichni boshlashga asos bo‘lishi mumkin.", "example": "Pilot filialda to‘lov hisoblari tekshirilib qabul qilindi.", "where": "Amaliy tekshiruv: Pilot filialda to‘lov hisoblari tekshirilib qabul qilindi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-10", "group": "business", "term": "Risk", "sub": "Noaniqlikdan keladigan ta’sir", "definition": "Kelajakdagi noaniq hodisaning maqsadga ta’siri. Ehtimol va oqibat baholanadi. Sodir bo‘lgan muammo bilan bir xil emas.", "example": "Eski Excel ma’lumoti sifatsiz bo‘lishi ko‘chirish muddatini uzaytirishi mumkin.", "where": "Amaliy tekshiruv: Eski Excel ma’lumoti sifatsiz bo‘lishi ko‘chirish muddatini uzaytirishi mumkin.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-11", "group": "business", "term": "Change management", "sub": "O‘zgarishni boshqarish", "definition": "Yangi ish usuliga o‘tishda odamlar va jarayonlarni tayyorlash. Tushuntirish, o‘rgatish va yordam kiradi. Dastur o‘rnatishning o‘zi xodimlar odatini o‘zgartirmaydi.", "example": "Davomat tizimi uchun o‘qituvchilarga qisqa trening beriladi.", "where": "Amaliy tekshiruv: Davomat tizimi uchun o‘qituvchilarga qisqa trening beriladi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-12", "group": "business", "term": "Agile", "sub": "Moslashuvchan ish yondashuvi", "definition": "Ishni qisqa bosqichlarda bajarib, fikr-mulohaza asosida moslashtirish. Rejasiz ishlash degani emas. Talab o‘zgarishi boshqarilishi kerak.", "example": "Avval murojaatlarni qabul qilish ishlanadi, natijaga qarab keyingi modul tanlanadi.", "where": "Amaliy tekshiruv: Avval murojaatlarni qabul qilish ishlanadi, natijaga qarab keyingi modul tanlanadi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-13", "group": "business", "term": "Kanban", "sub": "Ish oqimini ko‘rsatish usuli", "definition": "Vazifalarni holatlar bo‘yicha ko‘rsatib, bir paytdagi ish hajmini boshqarish. Taxta jarayonni tushunishga yordam beradi. Ustunlar jamoaning haqiqiy ishiga mos bo‘lishi kerak.", "example": "Rejada, bajarilmoqda va tayyor ustunlarida vazifalar yuritiladi.", "where": "Amaliy tekshiruv: Rejada, bajarilmoqda va tayyor ustunlarida vazifalar yuritiladi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "business-14", "group": "business", "term": "Feedback", "sub": "Fikr-mulohaza", "definition": "Ish yoki mahsulotni yaxshilash uchun kuzatuv va taklif. Aniq holat va ta’sir ko‘rsatilsa foydali bo‘ladi. Shaxsga baho berishdan ko‘ra xatti-harakatga e’tibor qilinadi.", "example": "Administrator ariza shaklida filial tanlash noqulayligini bildiradi.", "where": "Amaliy tekshiruv: Administrator ariza shaklida filial tanlash noqulayligini bildiradi.", "related": ["legacy-1", "legacy-18", "legacy-27"], "confusion": "", "cat": "Biznes va boshqaruv"}, {"id": "finance-0", "group": "finance", "term": "Revenue", "sub": "Savdo tushumi", "definition": "Mahsulot yoki xizmat sotilishidan hisoblangan daromad. Hisoblash usuliga qarab pul olish vaqti bilan farq qilishi mumkin. Xarajatlarni ayirmasdan uni sof foyda deyish noto‘g‘ri.", "example": "Kurs uchun hisoblangan 100 mln daromadning hammasi hali kassaga kelmagan bo‘lishi mumkin.", "where": "Amaliy tekshiruv: Kurs uchun hisoblangan 100 mln daromadning hammasi hali kassaga kelmagan bo‘lishi mumkin.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "Tushum yoki daromad foyda bilan bir xil emas.", "cat": "Moliya va buxgalteriya"}, {"id": "finance-1", "group": "finance", "term": "Profit", "sub": "Foyda", "definition": "Daromaddan tegishli xarajatlar ayrilgandan qoladigan natija. Yalpi, operatsion va sof foyda farqlanadi. Qaysi xarajatlar ayrilgani aytilishi kerak.", "example": "Kurs tushumidan o‘qituvchi haqi, ijara va boshqa xarajatlar ayriladi.", "where": "Amaliy tekshiruv: Kurs tushumidan o‘qituvchi haqi, ijara va boshqa xarajatlar ayriladi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-2", "group": "finance", "term": "Gross profit", "sub": "Yalpi foyda", "definition": "Savdo daromadidan sotilgan mahsulot yoki xizmat tannarxi ayrilgandagi natija. Barcha boshqa xarajatlar hali ayrilmagan bo‘lishi mumkin. Sof foyda bilan teng emas.", "example": "Mahsulot 100 mingga sotildi, tannarxi 60 ming: yalpi foyda 40 ming.", "where": "Amaliy tekshiruv: Mahsulot 100 mingga sotildi, tannarxi 60 ming: yalpi foyda 40 ming.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-3", "group": "finance", "term": "Margin", "sub": "Foyda ulushi", "definition": "Belgilangan foydaning savdo daromadiga nisbati. Ko‘pincha foizda ko‘rsatiladi. Tannarxga nisbatan hisoblangan ustama bilan aralashtirilmaydi.", "example": "100 ming savdoda 40 ming yalpi foyda bo‘lsa yalpi marja 40 foiz.", "where": "Amaliy tekshiruv: 100 ming savdoda 40 ming yalpi foyda bo‘lsa yalpi marja 40 foiz.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "Margin savdo daromadiga, markup esa tannarxga nisbatan hisoblanadi.", "cat": "Moliya va buxgalteriya"}, {"id": "finance-4", "group": "finance", "term": "Markup", "sub": "Tannarx ustidagi ustama", "definition": "Narxga qo‘shilgan summaning tannarxga nisbati. Marjadan farqli ravishda maxraj tannarx bo‘ladi. Qaysi xarajat tannarxga kirgani muhim.", "example": "60 ming tannarxga 30 ming qo‘shilsa ustama 50 foiz.", "where": "Amaliy tekshiruv: 60 ming tannarxga 30 ming qo‘shilsa ustama 50 foiz.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-5", "group": "finance", "term": "Budget", "sub": "Budjet", "definition": "Ma’lum davr yoki loyiha uchun rejalashtirilgan daromad va xarajatlar. Reja haqiqiy natija bilan solishtiriladi. Budjet mavjudligi pul allaqachon sarflandi degani emas.", "example": "AI pilot uchun 10 mln xarajat chegarasi belgilanadi.", "where": "Amaliy tekshiruv: AI pilot uchun 10 mln xarajat chegarasi belgilanadi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-6", "group": "finance", "term": "Fixed cost", "sub": "Doimiy xarajat", "definition": "Muayyan hajm oralig‘ida faoliyat soni o‘zgarsa ham deyarli o‘zgarmaydigan xarajat. Uzoq muddatda bu xarajat ham o‘zgarishi mumkin. Mutlaq o‘zgarmas degani emas.", "example": "Oylik ijara o‘quvchilar soni biroz oshganda bir xil qoladi.", "where": "Amaliy tekshiruv: Oylik ijara o‘quvchilar soni biroz oshganda bir xil qoladi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-7", "group": "finance", "term": "Variable cost", "sub": "O‘zgaruvchan xarajat", "definition": "Faoliyat hajmiga qarab o‘zgaradigan xarajat. Hisoblash davri va hajm mezoni aniq tanlanadi. Ba’zi xarajatlar aralash bo‘lishi mumkin.", "example": "Har o‘quvchiga beriladigan material xarajati o‘quvchi soni bilan oshadi.", "where": "Amaliy tekshiruv: Har o‘quvchiga beriladigan material xarajati o‘quvchi soni bilan oshadi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-8", "group": "finance", "term": "Break-even", "sub": "Zararsizlik nuqtasi", "definition": "Daromad va xarajat tenglashadigan savdo hajmi. Hisob narx va xarajat haqidagi taxminlarga bog‘liq. Bu darajada foyda hali nolga yaqin bo‘ladi.", "example": "Yangi guruh xarajatini qoplash uchun kamida nechta to‘lovchi kerakligi hisoblanadi.", "where": "Amaliy tekshiruv: Yangi guruh xarajatini qoplash uchun kamida nechta to‘lovchi kerakligi hisoblanadi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-9", "group": "finance", "term": "P&L", "sub": "Foyda va zarar hisoboti", "definition": "Davr daromadi, xarajatlari va moliyaviy natijasini ko‘rsatadi. Pul oqimi hisobotidan farq qiladi. Foyda borligi kassada pul yetarliligini anglatmaydi.", "example": "Oylik kurs daromadlari va markaz xarajatlari solishtiriladi.", "where": "Amaliy tekshiruv: Oylik kurs daromadlari va markaz xarajatlari solishtiriladi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-10", "group": "finance", "term": "Balance sheet", "sub": "Balans hisoboti", "definition": "Muayyan sanadagi aktiv, majburiyat va kapital holatini ko‘rsatadi. Davr davomida oqim emas, sanadagi holat beriladi. Bo‘limlar o‘zaro muvozanatda bo‘ladi.", "example": "Markaz jihozlari, pul mablag‘i va qarzlari yil oxirida ko‘rsatiladi.", "where": "Amaliy tekshiruv: Markaz jihozlari, pul mablag‘i va qarzlari yil oxirida ko‘rsatiladi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-11", "group": "finance", "term": "Asset", "sub": "Aktiv", "definition": "Tashkilot nazorat qiladigan va kelajakda iqtisodiy foyda keltirishi kutiladigan resurs. Faqat naqd pul bilan cheklanmaydi. Hisobga olish tegishli qoidalarga bog‘liq.", "example": "Kompyuter va bankdagi pul aktivlarga misol.", "where": "Amaliy tekshiruv: Kompyuter va bankdagi pul aktivlarga misol.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-12", "group": "finance", "term": "Liability", "sub": "Majburiyat", "definition": "Oldingi hodisalardan kelib chiqqan, bajarilishi resurs chiqishini talab qiladigan majburiyat. Faqat bank krediti emas. Muddati va summasi nazorat qilinadi.", "example": "Yetkazib beruvchiga jihoz uchun to‘lanishi kerak bo‘lgan qarz.", "where": "Amaliy tekshiruv: Yetkazib beruvchiga jihoz uchun to‘lanishi kerak bo‘lgan qarz.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-13", "group": "finance", "term": "Reconciliation", "sub": "Hisoblarni solishtirish", "definition": "Ikki manba yozuvlarini tekshirib farqlar sababini aniqlash. Tizimdagi raqamni haqiqiy bank yoki kassa bilan solishtirish mumkin. Tafovut shunchaki o‘chirib tashlanmaydi.", "example": "CRMda qayd etilgan to‘lovlar bank tushumlari bilan tekshiriladi.", "where": "Amaliy tekshiruv: CRMda qayd etilgan to‘lovlar bank tushumlari bilan tekshiriladi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "finance-14", "group": "finance", "term": "Depreciation", "sub": "Asosiy vosita qiymatini taqsimlash", "definition": "Aktivning amortizatsiyalanadigan qiymatini foydali muddatga taqsimlash. Bu har oy naqd pul chiqishi degani emas. Usul va muddat hisob siyosatiga bog‘liq.", "example": "Kompyuter xarajati foydalanish yillari bo‘yicha hisobga olinadi.", "where": "Amaliy tekshiruv: Kompyuter xarajati foydalanish yillari bo‘yicha hisobga olinadi.", "related": ["legacy-22", "legacy-23", "legacy-24"], "confusion": "", "cat": "Moliya va buxgalteriya"}, {"id": "education-0", "group": "education", "term": "Curriculum", "sub": "O‘quv dasturi", "definition": "O‘rganiladigan mavzular, maqsadlar va baholash tizimi. Faqat dars nomlari ro‘yxati emas. Bosqichlar o‘quvchi darajasi va natijaga mos bo‘lishi kerak.", "example": "Excel kursi formulalardan tahlil va loyiha bosqichiga o‘tadi.", "where": "Amaliy tekshiruv: Excel kursi formulalardan tahlil va loyiha bosqichiga o‘tadi.", "related": ["education-1", "education-2", "education-3"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-1", "group": "education", "term": "Syllabus", "sub": "Kurs rejasi va shartlari", "definition": "Kurs mazmuni, jadvali, topshiriqlar va baholash tartibini ko‘rsatadigan hujjat. O‘quvchiga nimani kutishni tushuntiradi. O‘quv dasturining kengroq tuzilmasidan farq qilishi mumkin.", "example": "O‘quvchi kurs boshida darslar va imtihon qoidalarini oladi.", "where": "Amaliy tekshiruv: O‘quvchi kurs boshida darslar va imtihon qoidalarini oladi.", "related": ["education-0", "education-2", "education-3"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-2", "group": "education", "term": "Learning outcome", "sub": "Kutilgan o‘quv natijasi", "definition": "O‘quvchi yakunda nima qila olishini aniq ifodalaydi. Faqat mavzu bilan tanishish emas, kuzatiladigan ko‘nikma bo‘lishi foydali. Baholash shu natijaga moslanadi.", "example": "O‘quvchi SUMIFS bilan shartli yig‘indini hisoblay oladi.", "where": "Amaliy tekshiruv: O‘quvchi SUMIFS bilan shartli yig‘indini hisoblay oladi.", "related": ["education-0", "education-1", "education-3"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-3", "group": "education", "term": "LMS", "sub": "O‘quv jarayoni platformasi", "definition": "Materiallar, topshiriqlar va o‘quv natijalarini boshqaradigan tizim. CRMning mijoz sotuvini yuritish vazifasidan farq qiladi. Ayrim tizimlar bir necha vazifani birlashtiradi.", "example": "Mentor dars materialini yuklab, topshiriq javoblarini qabul qiladi.", "where": "Amaliy tekshiruv: Mentor dars materialini yuklab, topshiriq javoblarini qabul qiladi.", "related": ["education-0", "education-1", "education-2"], "confusion": "LMS o‘quv jarayoniga, CRM mijozlar bilan ishlashga yo‘naltiriladi.", "cat": "Ta’lim"}, {"id": "education-4", "group": "education", "term": "Diagnostic assessment", "sub": "Boshlang‘ich diagnostika", "definition": "O‘quvchining mavjud bilim va ehtiyojini aniqlash uchun baholash. Mos daraja yoki guruh tanlashga yordam beradi. Natija butun qobiliyatning yakuniy bahosi emas.", "example": "Til kursiga kirishdan oldin daraja testi olinadi.", "where": "Amaliy tekshiruv: Til kursiga kirishdan oldin daraja testi olinadi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-5", "group": "education", "term": "Formative assessment", "sub": "Jarayon davomidagi baholash", "definition": "O‘rganish davomida xatolarni ko‘rib keyingi yordamni belgilash. Asosiy maqsad rivojlanish uchun fikr-mulohaza berish. Har safar yakuniy bahoga kiritilishi shart emas.", "example": "Dars oxiridagi kichik mashqdan qaysi mavzu tushunilmagani bilinadi.", "where": "Amaliy tekshiruv: Dars oxiridagi kichik mashqdan qaysi mavzu tushunilmagani bilinadi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-6", "group": "education", "term": "Summative assessment", "sub": "Yakuniy baholash", "definition": "Bosqich yakunida erishilgan natijani baholash. O‘quv maqsadlariga mos mezonlar ishlatiladi. Faqat bitta test turi bilan cheklanmaydi.", "example": "Modul oxirida test va amaliy loyiha baholanadi.", "where": "Amaliy tekshiruv: Modul oxirida test va amaliy loyiha baholanadi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-7", "group": "education", "term": "Rubric", "sub": "Baholash mezonlari jadvali", "definition": "Ishning qaysi jihati qanday darajada baholanishini ko‘rsatadi. O‘quvchi va mentor kutishni bir xil tushunadi. Mezonlar topshiriqdan oldin tushuntiriladi.", "example": "Loyihada aniqlik, mantiq va taqdimot alohida baholanadi.", "where": "Amaliy tekshiruv: Loyihada aniqlik, mantiq va taqdimot alohida baholanadi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-8", "group": "education", "term": "Pedagogy", "sub": "Ta’lim berish yondashuvi", "definition": "O‘qitish va o‘rganishni tashkil etish tamoyillari hamda usullari. Yosh, mavzu va sharoitga mos usul tanlanadi. Bitta usul barcha o‘quvchiga bir xil natija bermaydi.", "example": "Bolalar darsida tushuncha o‘yin va ko‘rgazmali misol bilan beriladi.", "where": "Amaliy tekshiruv: Bolalar darsida tushuncha o‘yin va ko‘rgazmali misol bilan beriladi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-9", "group": "education", "term": "Differentiation", "sub": "Ehtiyojga mos o‘qitish", "definition": "O‘quvchilar tayyorgarligi va ehtiyojiga qarab topshiriq yoki yordamni moslashtirish. Maqsadni asossiz pasaytirish degani emas. Guruh ichidagi farqlar hisobga olinadi.", "example": "Bir mavzu uchun asosiy va murakkabroq mashqlar beriladi.", "where": "Amaliy tekshiruv: Bir mavzu uchun asosiy va murakkabroq mashqlar beriladi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-10", "group": "education", "term": "Scaffolding", "sub": "Bosqichli yordam", "definition": "O‘quvchi mustaqil bajara olguncha vaqtinchalik tayanch berish. Ko‘nikma oshgani sari yordam kamaytiriladi. Doim tayyor javob berish bilan teng emas.", "example": "Avval formula namunasi, keyin qisman ko‘rsatma, oxirida mustaqil vazifa.", "where": "Amaliy tekshiruv: Avval formula namunasi, keyin qisman ko‘rsatma, oxirida mustaqil vazifa.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-11", "group": "education", "term": "Blended learning", "sub": "Aralash ta’lim", "definition": "Yuzma-yuz va onlayn o‘rganishni reja asosida birlashtirish. Har qismning vazifasi aniq bo‘ladi. Faqat Telegramga fayl yuborish bilan cheklanmaydi.", "example": "Nazariya video orqali, amaliy mashq sinfda bajariladi.", "where": "Amaliy tekshiruv: Nazariya video orqali, amaliy mashq sinfda bajariladi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-12", "group": "education", "term": "Flipped classroom", "sub": "Teskari sinf", "definition": "Dastlabki material darsdan oldin o‘rganilib, dars vaqti mashq va muhokamaga ajratiladi. Oldindan materialga kirish imkoniyati kerak. Tayyorlanmagan o‘quvchilar uchun yordam rejalashtiriladi.", "example": "O‘quvchi videoni ko‘rib keladi, darsda real jadvalni tahlil qiladi.", "where": "Amaliy tekshiruv: O‘quvchi videoni ko‘rib keladi, darsda real jadvalni tahlil qiladi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-13", "group": "education", "term": "Spaced repetition", "sub": "Oraliqli takrorlash", "definition": "Bilimni vaqt oralig‘ida qayta eslash orqali mustahkamlash. Bir kunda ko‘p qayta o‘qishdan boshqa usul. Oraliq qiyinlik va eslash natijasiga moslanishi mumkin.", "example": "Bugun o‘rganilgan termin bir necha kundan keyin yana tekshiriladi.", "where": "Amaliy tekshiruv: Bugun o‘rganilgan termin bir necha kundan keyin yana tekshiriladi.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "education-14", "group": "education", "term": "Active recall", "sub": "Faol eslash", "definition": "Javobga qaramasdan bilimni xotiradan tiklashga urinish. Keyin javob tekshirilib xato tuzatiladi. Oddiy qayta o‘qishdan farq qiladi.", "example": "CRM ta’rifini kartochkani ochmasdan aytib ko‘rish.", "where": "Amaliy tekshiruv: CRM ta’rifini kartochkani ochmasdan aytib ko‘rish.", "related": ["education-0", "education-1", "education-2"], "confusion": "", "cat": "Ta’lim"}, {"id": "logistics-0", "group": "logistics", "term": "Supply chain", "sub": "Ta’minot zanjiri", "definition": "Xomashyodan yakuniy mijozgacha mahsulot, ma’lumot va pul oqimlari. Bir nechta tashkilot va jarayon bog‘lanadi. Faqat transport bilan cheklanmaydi.", "example": "Yetkazib beruvchi, ombor, do‘kon va xaridor zanjiri.", "where": "Amaliy tekshiruv: Yetkazib beruvchi, ombor, do‘kon va xaridor zanjiri.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-1", "group": "logistics", "term": "Procurement", "sub": "Xaridni tashkil etish", "definition": "Talabni aniqlash, yetkazib beruvchini tanlash va xaridni boshqarish. Narxdan tashqari sifat, muddat va shartlar baholanadi. Buyurtma berish uning bir qismi.", "example": "Markaz kompyuter olganda kafolat va yetkazish ham solishtiriladi.", "where": "Amaliy tekshiruv: Markaz kompyuter olganda kafolat va yetkazish ham solishtiriladi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-2", "group": "logistics", "term": "Lead time", "sub": "Bajarilish oralig‘i", "definition": "Buyurtma yoki jarayon boshlanishidan yakunigacha ketgan vaqt. Qaysi boshlanish va yakun nuqtasi olinishi aytiladi. Yetkazish va ishlab chiqarish davrlari ajratilishi mumkin.", "example": "Material buyurtmasidan omborga kelishigacha 7 kun.", "where": "Amaliy tekshiruv: Material buyurtmasidan omborga kelishigacha 7 kun.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-3", "group": "logistics", "term": "Safety stock", "sub": "Xavfsizlik zaxirasi", "definition": "Talab yoki yetkazish noaniqligi uchun qo‘shimcha zaxira. Juda ko‘p zaxira pul va joyni band qiladi. Miqdor ma’lumotga asoslanadi.", "example": "Yetkazish kechiksa savdo to‘xtamasligi uchun qo‘shimcha mahsulot saqlanadi.", "where": "Amaliy tekshiruv: Yetkazish kechiksa savdo to‘xtamasligi uchun qo‘shimcha mahsulot saqlanadi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-4", "group": "logistics", "term": "Reorder point", "sub": "Qayta buyurtma chegarasi", "definition": "Qoldiq belgilangan darajaga tushganda yangi xarid boshlanadigan nuqta. Yetkazish vaqtidagi talab va xavfsizlik zaxirasi hisobga olinadi. Faqat qoldiq nol bo‘lganda buyurtma berish emas.", "example": "Qoldiq 50 donaga tushganda yangi partiya buyurtma qilinadi.", "where": "Amaliy tekshiruv: Qoldiq 50 donaga tushganda yangi partiya buyurtma qilinadi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-5", "group": "logistics", "term": "Stockout", "sub": "Zaxira tugashi", "definition": "Kerakli mahsulot talabni qondirish uchun mavjud bo‘lmagan holat. Savdo yoki ishlab chiqarishni to‘xtatishi mumkin. Sababi prognoz, qoldiq yoki yetkazish xatosi bo‘lishi mumkin.", "example": "Xaridor so‘ragan o‘lcham omborda qolmagan.", "where": "Amaliy tekshiruv: Xaridor so‘ragan o‘lcham omborda qolmagan.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-6", "group": "logistics", "term": "Overstock", "sub": "Ortiqcha zaxira", "definition": "Talabga nisbatan ortiqcha mahsulot saqlanishi. Pulni band qiladi va eskirish xavfini oshiradi. Ko‘p qoldiqning o‘zi har doim muammo emas, talab bilan solishtiriladi.", "example": "Sotilmayotgan kiyim modeli omborda ko‘payib qolgan.", "where": "Amaliy tekshiruv: Sotilmayotgan kiyim modeli omborda ko‘payib qolgan.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-7", "group": "logistics", "term": "FIFO", "sub": "Birinchi kirgan, birinchi chiqadi", "definition": "Avval kelgan mahsulotni avval chiqarish tamoyili. Ombor aylanishida yoki hisobda qo‘llanilishi mumkin, ularning ma’nosi ajratiladi. Muddati eng yaqin mahsulotni tanlash FEFOga tegishli.", "example": "Eski kelgan bir xil mahsulot partiyasi avval jo‘natiladi.", "where": "Amaliy tekshiruv: Eski kelgan bir xil mahsulot partiyasi avval jo‘natiladi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "FIFO kelgan tartibga, FEFO yaroqlilik muddatiga qaraydi.", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-8", "group": "logistics", "term": "FEFO", "sub": "Muddati oldin tugaydigan avval chiqadi", "definition": "Yaroqlilik muddati eng yaqin mahsulotni avval chiqarish. Kelgan sana bilan muddat bir xil tartibda bo‘lmasligi mumkin. Oziq-ovqat va dorilarda muhim.", "example": "Keyin kelgan, ammo muddati tezroq tugaydigan yogurt avval sotiladi.", "where": "Amaliy tekshiruv: Keyin kelgan, ammo muddati tezroq tugaydigan yogurt avval sotiladi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-9", "group": "logistics", "term": "WMS", "sub": "Omborni boshqarish tizimi", "definition": "Qabul, joylash, terish va jo‘natish kabi ombor amallarini boshqaradi. Oddiy qoldiq jadvalidan kengroq bo‘lishi mumkin. ERP bilan integratsiya qilinishi mumkin.", "example": "Xodim buyurtmadagi mahsulotni qaysi katakdan olishini ko‘radi.", "where": "Amaliy tekshiruv: Xodim buyurtmadagi mahsulotni qaysi katakdan olishini ko‘radi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-10", "group": "logistics", "term": "Pick and pack", "sub": "Terish va qadoqlash", "definition": "Buyurtmadagi mahsulotlarni ombordan yig‘ib, jo‘natishga tayyorlash. Miqdor va mahsulot mosligi tekshiriladi. Qadoqlash talabi mahsulotga bog‘liq.", "example": "Internet buyurtmasidagi 3 kiyim yig‘ilib qutiga solinadi.", "where": "Amaliy tekshiruv: Internet buyurtmasidagi 3 kiyim yig‘ilib qutiga solinadi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-11", "group": "logistics", "term": "Last mile", "sub": "Yakuniy yetkazish bosqichi", "definition": "Mahsulotni so‘nggi tarqatish nuqtasidan oluvchigacha yetkazish. Manzil, aloqa va kelishilgan vaqt muhim. Butun logistika jarayonining o‘zi emas.", "example": "Kuryer mahsulotni mahalliy ombordan xaridor uyiga olib boradi.", "where": "Amaliy tekshiruv: Kuryer mahsulotni mahalliy ombordan xaridor uyiga olib boradi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-12", "group": "logistics", "term": "Capacity planning", "sub": "Quvvatni rejalash", "definition": "Talabni bajarish uchun uskuna, odam yoki joy imkoniyatini hisoblash. Reja mavjud cheklovlarni hisobga oladi. Faqat material mavjudligi yetarli emas.", "example": "Buyurtma uchun stanok va ishchi soatlari yetarliligi tekshiriladi.", "where": "Amaliy tekshiruv: Buyurtma uchun stanok va ishchi soatlari yetarliligi tekshiriladi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-13", "group": "logistics", "term": "Production order", "sub": "Ishlab chiqarish buyurtmasi", "definition": "Qaysi mahsulotdan qancha va qachon ishlab chiqarish haqidagi topshiriq. Material, jarayon va natija bilan bog‘lanadi. Sotuv buyurtmasi bilan aynan bir hujjat emas.", "example": "100 dona stol ishlab chiqarish uchun ichki buyurtma ochiladi.", "where": "Amaliy tekshiruv: 100 dona stol ishlab chiqarish uchun ichki buyurtma ochiladi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "logistics-14", "group": "logistics", "term": "Quality control", "sub": "Sifat nazorati", "definition": "Mahsulot yoki natijaning belgilangan talablarga mosligini tekshirish. Namuna yoki barcha birliklar tekshirilishi mumkin. Sifatni yaratadigan jarayonlarni tashkil etishdan farq qiladi.", "example": "Tayyor kiyimning chok va o‘lchami tekshiriladi.", "where": "Amaliy tekshiruv: Tayyor kiyimning chok va o‘lchami tekshiriladi.", "related": ["legacy-2", "legacy-5", "legacy-20"], "confusion": "", "cat": "Logistika va ishlab chiqarish"}, {"id": "hr-0", "group": "hr", "term": "Recruitment", "sub": "Xodim izlash va tanlash", "definition": "Vakansiya ehtiyojini aniqlab nomzodlarni topish va baholash jarayoni. Talablar ishga mos bo‘lishi kerak. Faqat e’lon chiqarish bilan cheklanmaydi.", "example": "Markaz yangi administrator uchun nomzodlarni tanlaydi.", "where": "Amaliy tekshiruv: Markaz yangi administrator uchun nomzodlarni tanlaydi.", "related": ["hr-1", "hr-2", "hr-3"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-1", "group": "hr", "term": "Job description", "sub": "Lavozim vazifalari tavsifi", "definition": "Ishning vazifasi, mas’uliyati va kerakli ko‘nikmalarini yozadi. Nomzod va ish beruvchi kutishini aniqlashtiradi. Lavozim nomining o‘zi yetarli emas.", "example": "Sales manager uchun lidlar, qayta aloqa va hisobot vazifalari ko‘rsatiladi.", "where": "Amaliy tekshiruv: Sales manager uchun lidlar, qayta aloqa va hisobot vazifalari ko‘rsatiladi.", "related": ["hr-0", "hr-2", "hr-3"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-2", "group": "hr", "term": "CV", "sub": "Rezyume", "definition": "Tajriba, bilim va ishga mos natijalarni qisqa taqdim etadi. Vakansiyaga tegishli dalillar tanlanadi. Bilmagan vositalarni tajriba sifatida yozish ishonchga zarar qiladi.", "example": "Excel o‘qitish tajribasi va tayyorlangan loyihalar yoziladi.", "where": "Amaliy tekshiruv: Excel o‘qitish tajribasi va tayyorlangan loyihalar yoziladi.", "related": ["hr-0", "hr-1", "hr-3"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-3", "group": "hr", "term": "Portfolio", "sub": "Ish namunalari to‘plami", "definition": "Ko‘nikmani real bajarilgan ish bilan ko‘rsatadi. Muammo, yondashuv va natija tushuntiriladi. Boshqa odam ishini o‘ziniki deb ko‘rsatish mumkin emas.", "example": "Analitik tozalangan jadval va hisobot loyihasini ko‘rsatadi.", "where": "Amaliy tekshiruv: Analitik tozalangan jadval va hisobot loyihasini ko‘rsatadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-4", "group": "hr", "term": "Hard skills", "sub": "Kasbiy texnik ko‘nikmalar", "definition": "Muayyan vazifani bajarishga oid o‘rganiladigan bilim va ko‘nikmalar. Amaliy topshiriq bilan tekshirish mumkin. Sertifikatning o‘zi mahoratni to‘liq isbotlamaydi.", "example": "SQL so‘rovi yozish va Excelda hisoblash.", "where": "Amaliy tekshiruv: SQL so‘rovi yozish va Excelda hisoblash.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-5", "group": "hr", "term": "Soft skills", "sub": "Odamlar va ish bilan muomala", "definition": "Muloqot, hamkorlik va o‘zini boshqarish kabi ko‘nikmalar. Ishdagi xatti-harakat orqali namoyon bo‘ladi. Faqat ochiqko‘ngillik bilan teng emas.", "example": "Texnik muammoni mijozga sodda tushuntirish.", "where": "Amaliy tekshiruv: Texnik muammoni mijozga sodda tushuntirish.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-6", "group": "hr", "term": "Competency", "sub": "Vazifani bajarish qobiliyati", "definition": "Bilim, ko‘nikma va xatti-harakatning vazifaga mos birikmasi. Faqat nazariy bilim bilan cheklanmaydi. Kuzatiladigan mezon bilan baholash foydali.", "example": "Administrator muammoni aniqlab, qayd qilib va mas’ulga topshira oladi.", "where": "Amaliy tekshiruv: Administrator muammoni aniqlab, qayd qilib va mas’ulga topshira oladi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-7", "group": "hr", "term": "Onboarding", "sub": "Yangi xodimni moslashtirish", "definition": "Ish, jamoa va tizimlarni tushunishga yordam beradigan boshlang‘ich jarayon. Ruxsatlar, yo‘riqnoma va yordamchi mas’ul kerak bo‘ladi. Birinchi kundagi tanishtirish bilangina tugamaydi.", "example": "Yangi sotuvchi mahsulot va CRM bo‘yicha mashq qiladi.", "where": "Amaliy tekshiruv: Yangi sotuvchi mahsulot va CRM bo‘yicha mashq qiladi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-8", "group": "hr", "term": "Probation", "sub": "Sinov davri", "definition": "Ishning ikki tomonga mosligini baholash davri. Vazifa va baholash mezonlari oldindan aniq bo‘lishi kerak. Aniq huquqiy tartib shartnoma va mahalliy qonunga bog‘liq.", "example": "Sinov oyida suhbat sifati va qayta aloqa tartibi baholanadi.", "where": "Amaliy tekshiruv: Sinov oyida suhbat sifati va qayta aloqa tartibi baholanadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-9", "group": "hr", "term": "Performance review", "sub": "Ish natijasini ko‘rib chiqish", "definition": "Davr natijalari, ko‘nikma va rivojlanish ehtiyojini muhokama qilish. Dalil va kelishilgan mezonlar ishlatiladi. Faqat tanbeh berish uchrashuvi emas.", "example": "Rahbar xodim bilan oy natijasi va keyingi maqsadni kelishadi.", "where": "Amaliy tekshiruv: Rahbar xodim bilan oy natijasi va keyingi maqsadni kelishadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-10", "group": "hr", "term": "One-on-one", "sub": "Yakka uchrashuv", "definition": "Rahbar va xodimning muntazam suhbat va muvofiqlashtirish vaqti. To‘siqlar va yordam ehtiyoji muhokama qilinadi. Barcha vaqt hisobot o‘qishga ketmasligi kerak.", "example": "Yangi sotuvchi qiyin savollar bo‘yicha menejer bilan maslahatlashadi.", "where": "Amaliy tekshiruv: Yangi sotuvchi qiyin savollar bo‘yicha menejer bilan maslahatlashadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-11", "group": "hr", "term": "Career path", "sub": "Kasbiy rivojlanish yo‘li", "definition": "Keyingi rollar va ularga kerakli ko‘nikmalar ketma-ketligi. Har odamning yo‘li bir xil emas. Lavozim o‘sishi bilan bilim o‘sishi ham rejalashtiriladi.", "example": "Junior analitikdan mustaqil BI mutaxassisiga o‘tish ko‘nikmalari belgilanadi.", "where": "Amaliy tekshiruv: Junior analitikdan mustaqil BI mutaxassisiga o‘tish ko‘nikmalari belgilanadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-12", "group": "hr", "term": "Upskilling", "sub": "Mavjud yo‘nalishda bilimni oshirish", "definition": "Hozirgi kasb uchun yangi yoki chuqurroq ko‘nikma olish. Butunlay boshqa kasbga o‘tishdan farq qiladi. O‘rganish amaliy vazifaga bog‘lansa foydali.", "example": "Excel mutaxassisi Power Queryni o‘rganadi.", "where": "Amaliy tekshiruv: Excel mutaxassisi Power Queryni o‘rganadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-13", "group": "hr", "term": "Reskilling", "sub": "Yangi yo‘nalish uchun qayta o‘rganish", "definition": "Boshqa turdagi ishga o‘tish uchun yangi ko‘nikmalar olish. Mavjud tajribaning ayrim qismlari ko‘chishi mumkin. O‘tish vaqt va amaliy mashq talab qiladi.", "example": "Administrator analitika uchun SQL va ma’lumot modelini o‘rganadi.", "where": "Amaliy tekshiruv: Administrator analitika uchun SQL va ma’lumot modelini o‘rganadi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}, {"id": "hr-14", "group": "hr", "term": "ATS", "sub": "Nomzodlarni kuzatish tizimi", "definition": "Arizalar va tanlash bosqichlarini boshqaradigan dastur. HRga nomzodlar tarixini ko‘rishga yordam beradi. Har ATS avtomatik ravishda to‘g‘ri nomzodni tanlamaydi.", "example": "Rezyumelar yangi, suhbat va taklif bosqichlarida yuritiladi.", "where": "Amaliy tekshiruv: Rezyumelar yangi, suhbat va taklif bosqichlarida yuritiladi.", "related": ["hr-0", "hr-1", "hr-2"], "confusion": "", "cat": "HR va karyera"}];
